      + "grafik tahap " + GFX.lvl + "  DPR " + (renderer ? renderer.getPixelRatio() : "-") + "  panggilan " + (inf ? inf.render.calls : "-") + "  segi tiga " + (inf ? inf.render.triangles : "-") + "  geometri " + (inf ? inf.memory.geometries : "-") + "  tekstur " + (inf ? inf.memory.textures : "-") + "\n"
      + "SSE " + Math.round(DIAG.sse / s) + "/s  PATCH " + Math.round(DIAG.patch / s) + "/s  ping " + Net.ping() + "ms  pemain jauh " + (typeof remotes !== "undefined" ? remotes.size : 0) + "  ralat " + DIAG.err + (DIAG.last ? " (" + DIAG.last + ")" : "");
