if (SUBJ === "sj") { DATA.tema = DATA_SJ.tema; DATA.topik = DATA_SJ.topik; DATA.soalan = DATA_SJ.soalan; }
if (SUBJ === "sc") { DATA.tema = DATA_SC.tema; DATA.topik = DATA_SC.topik; DATA.soalan = DATA_SC.soalan; }
if (SUBJ === "mt") { DATA.tema = DATA_MT.tema; DATA.topik = DATA_MT.topik; DATA.soalan = DATA_MT.soalan; }
