document.documentElement.setAttribute("data-sj", SUBJ);
try { const vt = document.getElementById("verTap"); if (vt && SUBJS[SUBJ]) vt.textContent = SUBJS[SUBJ].nama + " \u00b7 v18.13"; } catch (e) { /* abaikan */ }
