/* kod buka subjek berkunci (untuk guru) */
function sjAskCode(k) {
  const old = document.getElementById("sjKeyOv"); if (old) old.remove();
  const ov = el("div", { class: "overlay", id: "sjKeyOv", style: "z-index:96" }), w = el("div", { class: "mcard" });
  const inp = el("input", { type: "password", inputmode: "numeric", autocomplete: "off", maxlength: "8", "aria-label": "Kod guru", style: "width:100%;font-size:22px;letter-spacing:.3em;text-align:center;padding:10px;border-radius:12px" }), msg = el("p", { class: "muted", "aria-live": "polite" }, "");
  const go = () => { if (inp.value.trim() === "6171") { try { localStorage.setItem(SJ_KEY, "6171"); } catch (e) { /* abaikan */ } ov.remove(); toast("Semua subjek telah dibuka.", "ok"); setSubject(k); } else { msg.textContent = "Kod tidak sah. Minta kod daripada pentadbir GEMPUR."; inp.select(); } };
  inp.addEventListener("keydown", (e) => { if (e.key === "Enter") go(); if (e.key === "Escape") ov.remove(); });
  const ok = el("button", { type: "button", class: "btn" }, "Buka subjek"), cl = el("button", { type: "button", class: "btn alt" }, "Batal"); ok.addEventListener("click", go); cl.addEventListener("click", () => ov.remove());
  w.append(el("h2", null, "🔒 " + SUBJS[k].subjek + " dikunci"), el("p", null, "Buat masa ini GEMPUR dibuka untuk Tasawwur Islam dan Pendidikan Islam (Tingkatan 3, 4 dan 5). Guru yang ingin menggunakan subjek lain perlu memasukkan kod akses."), inp, msg, el("div", { class: "row" }, ok, cl));
  ov.appendChild(w); ov.addEventListener("click", (e) => { if (e.target === ov) ov.remove(); }); document.body.appendChild(ov); setTimeout(() => inp.focus(), 50);
}
const RS_F = ["xp", "la", "ad", "ld", "wk", "wp", "mk", "mp", "kh", "lz"];
function swapRank(from, to) {
  P.rs = P.rs && typeof P.rs === "object" ? P.rs : {};
  const o = {}; RS_F.forEach((f) => { o[f] = P[f]; });
  P.rs[from] = o;
  const n = P.rs[to] || {};
  RS_F.forEach((f) => { P[f] = n[f] !== undefined ? n[f] : (f === "kh" ? {} : (f === "wk" || f === "mk" || f === "ld") ? "" : 0); });
  delete P.rs[to];
}
const NSUF = { pi: "_pi", ba: "_ba", p3: "_p3", sj: "_sj", sc: "_sc", mt: "_mt", bm: "_bm", bi: "_bi" };
function docSj(id) { const x = String(id).slice(-3); return x === "_pi" ? "pi" : x === "_ba" ? "ba" : x === "_p3" ? "p3" : x === "_sj" ? "sj" : x === "_sc" ? "sc" : x === "_mt" ? "mt" : x === "_bm" ? "bm" : x === "_bi" ? "bi" : "tw"; }
function docUid(id) { return docSj(id) === "tw" ? String(id) : String(id).slice(0, -3); }
function nkey(uid) { return uid + (NSUF[SUBJ] || ""); }
