function qValid(q, nt) {
  return !!q && Number.isInteger(q.i) && q.i >= 0 && (!!nt || !!TOPIK[q.t]) && q.d >= 1 && q.d <= 3 && typeof q.q === "string" && q.q.trim().length > 3
    && Array.isArray(q.o) && q.o.length === 4 && q.o.every((o) => typeof o === "string" && o.trim()) && new Set(q.o.map((o) => o.trim().toLowerCase())).size === 4
    && Number.isInteger(q.a) && q.a >= 0 && q.a <= 3;
}
function qbankBuild() {
  for (const k in BYTOPIK) delete BYTOPIK[k];
  for (const k in QBYID) delete QBYID[k];
  QLIST = []; RLIST = []; QB.bad = 0; QB.off = 0;
  DATA.soalan.forEach((q) => {
    if (q && q.x === 1) { QB.off++; return; }
    if (q && (q.t === "P3-R" || q.t === "TW-R")) { if (qValid(q, 1) && !QBYID[q.i]) { RLIST.push(q); QBYID[q.i] = q; } else QB.bad++; return; }
    if (!qValid(q) || QBYID[q.i]) { QB.bad++; return; }
    QLIST.push(q); QBYID[q.i] = q; (BYTOPIK[q.t] || (BYTOPIK[q.t] = [])).push(q);
  });
  QB.n = QLIST.length;
}
qbankBuild();
function qbankApply(j, src) {
  if (!j || !Array.isArray(j.soalan)) return false;
  const list = j.soalan.map((x) => ({ i: Number(x && (x.id != null ? x.id : x.i)), t: String((x && x.t) || ""), d: Number(x && x.d) || 0, q: String((x && x.q) || "").trim(), o: Array.isArray(x && x.o) ? x.o.map((o) => String(o == null ? "" : o).trim()) : [], a: Number(x && x.a), e: String((x && x.e) || "").trim(), s: String((x && x.s) || "").trim(), x: x && x.status === "gantung" ? 1 : 0 }));
  const saved = DATA.soalan;
  DATA.soalan = list; qbankBuild();
  if (QB.n < 50) { DATA.soalan = saved; qbankBuild(); return false; } /* fail rosak: kekalkan bank terdahulu */
  QB.src = src; QB.ver = String(j.versi || "");
  return true;
}
/* v18.13: tiada lagi salinan terbenam; semua subjek menunggu fail JSON (atau salinan tersimpan) sebelum boleh bermain */
function qbankWait(st) {
  let o = $("qbWait");
  if (!st) { if (o) o.remove(); return; }
  if (!o) { o = el("div", { class: "overlay", id: "qbWait", role: "alertdialog", "aria-live": "polite", style: "z-index:75" }); document.body.appendChild(o); }
  o.textContent = "";
  const c = el("div", { class: "mcard" }, el("h1", null, SUBJS[SUBJ].nama));
  if (st === "load") c.append(el("p", null, "Memuatkan bank soalan..."));
  else {
    c.append(el("p", null, "Bank soalan tidak dapat dimuatkan. Semak sambungan internet, kemudian cuba lagi."));
    const r = el("button", { class: "btn", type: "button" }, "Cuba lagi"), t = el("button", { class: "btn alt", type: "button" }, "Tukar ke " + SUBJS.tw.nama);
    r.addEventListener("click", () => qbankLoad());
    t.addEventListener("click", () => setSubject("tw"));
    c.append(el("div", { class: "row" }, r, t));
  }
  o.appendChild(c);
}
async function qbankLoad() {
  let j = null, src = "", c = null;
  try { c = JSON.parse(localStorage.getItem(SUBJS[SUBJ].cache) || "null"); if (!(c && Array.isArray(c.soalan) && String(c.versi || "") >= QB.ver)) c = null; } catch (e) { c = null; }
  if (!QB.n && c && qbankApply(c, "simpanan")) { try { renderAll(); } catch (e) { /* abaikan */ } }
  if (!QB.n) qbankWait("load");
  try { const r = await fetch(SUBJS[SUBJ].fail, { cache: "no-cache" }); if (r.ok) { j = await r.json(); src = "soalan.json"; } } catch (e) { j = null; }
  if (j && !(Array.isArray(j.soalan) && j.soalan.length)) j = null;
  if (j) { try { localStorage.setItem(SUBJS[SUBJ].cache, JSON.stringify(j)); } catch (e) { /* abaikan */ } }
  else if (c && QB.src !== "simpanan") { j = c; src = "simpanan"; }
  if (j && qbankApply(j, src)) { try { renderAll(); } catch (e) { /* abaikan */ } }
  qbankWait(QB.n ? "" : "gagal");
}
function qbankInfo() { return "Bank soalan: " + QB.n + " soalan aktif (" + (QB.src === "soalan.json" ? "soalan.json" : QB.src === "simpanan" ? "salinan tersimpan" : "salinan terbenam") + (QB.ver ? ", versi " + QB.ver : "") + ")" + (QB.off ? ", " + QB.off + " digantung" : "") + (QB.bad ? ", " + QB.bad + " tidak sah diabaikan" : "") + "."; }

