    const k = String(s.negeri || "").toUpperCase(); if (!k) continue;
    const o = g[k] || (g[k] = { negeri: k, skor: 0, sekolah: 0, bil: 0, list: [], top: null });
    o.list.push(s.skor); o.sekolah++; o.bil += s.bil; if (!o.top) o.top = s;
