  const cur = { sid: sid, wk: weekKey(), mk: monthKey(), w: pos(wb, (r) => r.sid === sid), m: pos(mb, (r) => r.sid === sid), a: pos(ab, (r) => r.sid === sid), s: pos(wr, (r) => r.negeri === me) };
