function seasonTick() {
  const n = seasonNo(Date.now());
  if (n < 1 || n > SEASON_GEN) return;
  if (!P.ss || P.ss.n !== n) P.ss = { n: n, best: 0, nw: [] };
  const r = myRank();
  let ch = false;
  if (r > P.ss.best && (r < 10 || Net.stand)) { P.ss.best = r; ch = true; }
  SEASON_TIER.forEach((t, i) => {
    const bid = "ms" + n + "_" + (i + 1);
    if (P.ss.best < t.r || P.bd[bid] || (t.r >= 10 && !Net.stand)) return;
    P.bd[bid] = Date.now(); P.coin = (P.coin | 0) + t.c; ch = true;
    if (t.a) { const id = "s" + n + t.a; if (P.accOwn.indexOf(id) < 0) P.accOwn.push(id); }
    if (t.rk) P.sr = clamp((P.sr | 0) + 1, 0, ROCK_CAP);
    (P.ss.nw || (P.ss.nw = [])).push("Lencana Musim " + n + " " + t.n + " (+" + t.c + " syiling" + (t.a ? ", aksesori eksklusif" : "") + (t.rk ? ", +1 roket" : "") + ")");
  });
  if (ch) saveP();
}
