/* ---------- Sijil pencapaian peringkat kebangsaan (PDF) ----------
   Dilukis pada kanvas (A4 melintang, 300 dpi) kemudian dibungkus sebagai PDF satu halaman.
   Tiada pustaka luar. Bukan sijil rasmi kerajaan. */
const CERT = { issuer: "sistemguru.my" };
const BULAN = ["Januari", "Februari", "Mac", "April", "Mei", "Jun", "Julai", "Ogos", "September", "Oktober", "November", "Disember"];

function certNo(now) {
  const s = (Net.uid || "") + "|" + P.nama + "|" + mySid() + "|" + Math.round(P.xp) + "|" + totals().m;
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
  const d = new Date(now);
  return "GT-" + d.getFullYear() + String(d.getMonth() + 1).padStart(2, "0") + "-" + h.toString(36).toUpperCase().padStart(6, "0").slice(0, 6);
}

function certSvgImage(svg) {
  return new Promise((res) => {
    const img = new Image();
    img.onload = () => res(img);
    img.onerror = () => res(null);
    img.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg.replace("<svg ", '<svg xmlns="http://www.w3.org/2000/svg" '));
  });
}

function certHex(g, cx, cy, r, rot) {
  g.beginPath();
  for (let i = 0; i < 6; i++) { const a = rot + i * Math.PI / 3; g[i ? "lineTo" : "moveTo"](cx + Math.cos(a) * r, cy + Math.sin(a) * r); }
  g.closePath();
}
function certStar(g, cx, cy, r, ri) {
  g.beginPath();
  for (let i = 0; i < 10; i++) { const a = -Math.PI / 2 + i * Math.PI / 5, rr = i % 2 ? ri : r; g[i ? "lineTo" : "moveTo"](cx + Math.cos(a) * rr, cy + Math.sin(a) * rr); }
  g.closePath();
}
function certRosette(g, cx, cy, R, r, d, col, lw) {
  g.strokeStyle = col; g.lineWidth = lw; g.beginPath();
  for (let t = 0; t <= 60 * Math.PI; t += 0.02) {
    const k = (R - r) / r;
    const x = cx + (R - r) * Math.cos(t) + d * Math.cos(k * t), y = cy + (R - r) * Math.sin(t) - d * Math.sin(k * t);
    t === 0 ? g.moveTo(x, y) : g.lineTo(x, y);
  }
  g.stroke();
}
function certText(g, txt, x, y, font, color, align, spacing, maxW) {
  g.font = font; g.fillStyle = color; g.textAlign = align || "center"; g.textBaseline = "alphabetic";
  try { g.letterSpacing = (spacing || 0) + "px"; } catch (e) { /* abaikan */ }
  if (maxW) {
    let size = parseFloat(/(\d+(\.\d+)?)px/.exec(font)[1]);
    while (g.measureText(txt).width > maxW && size > 20) { size -= 2; g.font = font.replace(/\d+(\.\d+)?px/, size + "px"); }
  }
  g.fillText(txt, x, y);
  try { g.letterSpacing = "0px"; } catch (e) { /* abaikan */ }
}

async function certLoadFonts() {
  if (!document.fonts || !document.fonts.load) return;
  const want = ["700 40px Cinzel", "600 40px Cinzel", "600 40px 'Cormorant Garamond'", "italic 500 40px 'Cormorant Garamond'", "500 24px Barlow", "600 24px Barlow"];
  try { await Promise.race([Promise.all(want.map((f) => document.fonts.load(f))), new Promise((r) => setTimeout(r, 3500))]); } catch (e) { /* abaikan */ }
}

async function certCanvas(scale) {
  await certLoadFonts();
  const now = Date.now(), W = 1754, H = 1240;
  const c = document.createElement("canvas");
  c.width = W * scale; c.height = H * scale;
  const g = c.getContext("2d");
  g.scale(scale, scale);
  const NAVY = "#0f1f45", GOLD = "#b8902c", GOLD2 = "#d9b44a", RED = "#8c1d2c", PAPER = "#fbf7ec", INK = "#2a2a2a", MUTE = "#5c5a52";
  const SERIF = "'Cormorant Garamond', Georgia, 'Times New Roman', serif", CAPS = "Cinzel, 'Times New Roman', serif", SANS = "Barlow, Arial, sans-serif";
  const ri = myRank(), rank = RANKS[ri], tt = totals();

  g.fillStyle = PAPER; g.fillRect(0, 0, W, H);
  // corak guilloche halus
  g.save(); g.globalAlpha = 0.5;
  certRosette(g, W / 2, H / 2 + 30, 520, 173, 240, "rgba(184,144,44,0.14)", 1.2);
  certRosette(g, W / 2, H / 2 + 30, 430, 113, 190, "rgba(15,31,69,0.07)", 1);
  g.restore();
  // jalur sisi
  g.fillStyle = NAVY; g.fillRect(0, 0, 18, H); g.fillRect(W - 18, 0, 18, H);
  g.fillStyle = GOLD; g.fillRect(18, 0, 4, H); g.fillRect(W - 22, 0, 4, H);
  // bingkai
  g.strokeStyle = NAVY; g.lineWidth = 10; g.strokeRect(48, 48, W - 96, H - 96);
  g.strokeStyle = GOLD; g.lineWidth = 3; g.strokeRect(66, 66, W - 132, H - 132);
  g.strokeStyle = NAVY; g.lineWidth = 1.5; g.strokeRect(78, 78, W - 156, H - 156);
  // hiasan penjuru
  [[78, 78, 1, 1], [W - 78, 78, -1, 1], [78, H - 78, 1, -1], [W - 78, H - 78, -1, -1]].forEach(([x, y, sx, sy]) => {
    g.save(); g.translate(x, y); g.scale(sx, sy);
    g.fillStyle = GOLD; g.beginPath(); g.moveTo(0, 0); g.lineTo(70, 0); g.lineTo(0, 70); g.closePath(); g.fill();
    g.fillStyle = NAVY; g.beginPath(); g.moveTo(0, 0); g.lineTo(44, 0); g.lineTo(0, 44); g.closePath(); g.fill();
    g.fillStyle = PAPER; certStar(g, 20, 20, 12, 5); g.fill();
    g.restore();
  });

  // lambang program (heksagon dan bintang)
  g.fillStyle = NAVY; certHex(g, W / 2, 156, 56, Math.PI / 6); g.fill();
  g.strokeStyle = GOLD2; g.lineWidth = 4; certHex(g, W / 2, 156, 56, Math.PI / 6); g.stroke();
  g.strokeStyle = GOLD2; g.lineWidth = 1.5; certHex(g, W / 2, 156, 47, Math.PI / 6); g.stroke();
  g.fillStyle = GOLD2; certStar(g, W / 2, 156, 27, 11); g.fill();
  certText(g, "PROGRAM GEMPUR " + SUBJS[SUBJ].subjek.toUpperCase(), W / 2, 248, "600 26px " + CAPS, NAVY, "center", 7);

  certText(g, "SIJIL PENCAPAIAN", W / 2, 336, "700 86px " + CAPS, NAVY, "center", 6, 1250);
  certText(g, "PERINGKAT KEBANGSAAN", W / 2, 396, "700 34px " + CAPS, RED, "center", 9);
  g.font = "700 34px " + CAPS; try { g.letterSpacing = "9px"; } catch (e) { /* abaikan */ }
  const hw = g.measureText("PERINGKAT KEBANGSAAN").width / 2; try { g.letterSpacing = "0px"; } catch (e) { /* abaikan */ }
  g.strokeStyle = GOLD; g.lineWidth = 2.5;
  g.beginPath(); g.moveTo(W / 2 - hw - 190, 384); g.lineTo(W / 2 - hw - 30, 384); g.moveTo(W / 2 + hw + 30, 384); g.lineTo(W / 2 + hw + 190, 384); g.stroke();

  certText(g, "Dengan ini disahkan bahawa", W / 2, 462, "italic 500 34px " + SERIF, MUTE, "center", 0);
  certText(g, cleanFull(P.penuh || P.nama).toUpperCase(), W / 2, 556, "600 96px " + SERIF, NAVY, "center", 3, 1300);
  g.strokeStyle = GOLD; g.lineWidth = 2; g.beginPath(); g.moveTo(W / 2 - 330, 580); g.lineTo(W / 2 + 330, 580); g.stroke();
  const asal = [cleanSekolah(P.sekolah), negeriNama(P.negeri)].filter(Boolean).join(", ") + (P.kelas ? " | " + P.kelas : "");
  certText(g, asal, W / 2, 630, "600 30px " + SANS, INK, "center", 1.5, 1350);

  certText(g, "telah menunjukkan penguasaan dalam pembelajaran kendiri " + SUBJS[SUBJ].subjek + (SUBJ === "p3" ? "" : " SPM"), W / 2, 692, "italic 500 35px " + SERIF, INK, "center", 0);
  certText(g, "melalui permainan Gempur dan dianugerahkan pangkat", W / 2, 734, "italic 500 35px " + SERIF, INK, "center", 0);
  certText(g, rank.n.toUpperCase(), W / 2, 818, "700 66px " + CAPS, RED, "center", 5, 1250);

  // kotak statistik
  const stands = Net.stand ? "#" + Net.stand.pos + " / " + Net.stand.n : "-";
  const stats = [[String(Math.round(curXp())), "Mata pangkat"], [tt.m + " / " + DATA.topik.length, "Misi diselesaikan"], [String(tt.st), "Bintang"], [stands, "Kedudukan kebangsaan"]];
  const bw = 330, gap = 26, x0 = W / 2 - (bw * 4 + gap * 3) / 2, by = 858;
  stats.forEach((s, i) => {
    const x = x0 + i * (bw + gap);
    g.fillStyle = "rgba(15,31,69,0.05)"; g.fillRect(x, by, bw, 94);
    g.strokeStyle = "rgba(184,144,44,0.7)"; g.lineWidth = 1.5; g.strokeRect(x, by, bw, 94);
    g.fillStyle = GOLD; g.fillRect(x, by, 6, 94);
    certText(g, s[0], x + bw / 2, by + 50, "700 42px " + CAPS, NAVY, "center", 1, bw - 30);
    certText(g, s[1].toUpperCase(), x + bw / 2, by + 79, "600 16px " + SANS, MUTE, "center", 2.5);
  });

  // pengesahan: tarikh, mohor, tandatangan
  const d = new Date(now), tarikh = d.getDate() + " " + BULAN[d.getMonth()] + " " + d.getFullYear();
  const ly = 1066;
  g.strokeStyle = NAVY; g.lineWidth = 1.5;
  g.beginPath(); g.moveTo(190, ly); g.lineTo(520, ly); g.moveTo(W - 520, ly); g.lineTo(W - 190, ly); g.stroke();
  certText(g, tarikh, 355, ly - 14, "italic 600 34px " + SERIF, NAVY, "center", 0);
  certText(g, "TARIKH", 355, ly + 26, "600 16px " + SANS, MUTE, "center", 3);
  certText(g, CERT.issuer, W - 355, ly - 14, "italic 700 34px " + SERIF, NAVY, "center", 0);
  certText(g, "DIKELUARKAN OLEH", W - 355, ly + 26, "600 16px " + SANS, MUTE, "center", 3);

  // mohor tengah
  const sx = W / 2, sy = 1040;
  g.fillStyle = GOLD; g.beginPath(); for (let i = 0; i < 32; i++) { const a = i * Math.PI / 16, r = i % 2 ? 70 : 80; g[i ? "lineTo" : "moveTo"](sx + Math.cos(a) * r, sy + Math.sin(a) * r); } g.closePath(); g.fill();
  g.fillStyle = NAVY; g.beginPath(); g.arc(sx, sy, 63, 0, Math.PI * 2); g.fill();
  g.strokeStyle = GOLD2; g.lineWidth = 2.5; g.beginPath(); g.arc(sx, sy, 56, 0, Math.PI * 2); g.stroke();
  const img = await certSvgImage(insignia(ri, 100));
  if (img) g.drawImage(img, sx - 27, sy - 38, 54, 54);
  certText(g, "KEBANGSAAN", sx, sy + 38, "700 11px " + CAPS, GOLD2, "center", 2.5);

  certText(g, "No. sijil: " + certNo(now), W / 2, 1136, "500 17px " + SANS, MUTE, "center", 2);
  certText(g, "Sijil ini dikeluarkan oleh sistemguru.my melalui program Gempur dan bukan sijil rasmi Kementerian Pendidikan Malaysia.", W / 2, 1156, "500 14px " + SANS, MUTE, "center", 0.5);
  return c;
}

function certPdf(jpg, w, h) {
  const enc = new TextEncoder(), parts = [], offs = [];
  let off = 0;
  const push = (u8) => { parts.push(u8); off += u8.length; };
  const str = (s) => push(enc.encode(s));
  const content = "q 842 0 0 595 0 0 cm /Im0 Do Q";
  str("%PDF-1.4\n");
  offs[1] = off; str("1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n");
  offs[2] = off; str("2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n");
  offs[3] = off; str("3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /XObject << /Im0 5 0 R >> >> /Contents 4 0 R >>\nendobj\n");
  offs[4] = off; str("4 0 obj\n<< /Length " + content.length + " >>\nstream\n" + content + "\nendstream\nendobj\n");
  offs[5] = off; str("5 0 obj\n<< /Type /XObject /Subtype /Image /Width " + w + " /Height " + h + " /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length " + jpg.length + " >>\nstream\n");
  push(jpg); str("\nendstream\nendobj\n");
  offs[6] = off; str("6 0 obj\n<< /Title (Sijil Pencapaian Gempur) /Producer (Gempur) >>\nendobj\n");
  const xr = off;
  let x = "xref\n0 7\n0000000000 65535 f \n";
  for (let i = 1; i <= 6; i++) x += String(offs[i]).padStart(10, "0") + " 00000 n \n";
  str(x + "trailer\n<< /Size 7 /Root 1 0 R /Info 6 0 R >>\nstartxref\n" + xr + "\n%%EOF\n");
  return new Blob(parts, { type: "application/pdf" });
}

async function saveFile(blob, name) {
  try {
    if (window.claude && typeof window.claude.use === "function") {
      const dl = await window.claude.use("downloads");
      if (dl) { await dl.save({ filename: name, data: blob }); return "ok"; }
    }
  } catch (e) { if (e && e.code === "declined") return "declined"; }
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob); a.download = name;
  document.body.appendChild(a); a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 5000);
  return "ok";
}

function certEligible() { return !!(P.nama && P.sekolah && totals().m >= 1); }

async function downloadCertificate() {
  if (!certEligible()) return "belum";
  let scale = 2, jpg = null, c = null;
  for (const sc of [2, 1]) {
    try {
      c = await certCanvas(sc); scale = sc;
      const blob = await new Promise((r) => c.toBlob(r, "image/jpeg", 0.93));
      if (blob) { jpg = new Uint8Array(await blob.arrayBuffer()); break; }
    } catch (e) { /* cuba saiz lebih kecil */ }
  }
  if (!jpg) return "gagal";
  const pdf = certPdf(jpg, 1754 * scale, 1240 * scale);
  const nama = "Sijil-Gempur-" + cleanFull(P.penuh || P.nama).replace(/[^A-Za-z0-9]+/g, "-").replace(/^-+|-+$/g, "") + ".pdf";
  return saveFile(pdf, nama);
}

