  const w = b.x1 - b.x0, h = b.y1 - b.y0, r = Math.max(w, h) * 0.045;
  const mp = DATA.negeri[id];
  if (!_tourM) { _tourM = sv("svg", { width: "0", height: "0", style: "position:absolute;visibility:hidden" }); document.body.appendChild(_tourM); }
  const mpath = sv("path", { d: mp.d }); _tourM.textContent = ""; _tourM.appendChild(mpath);
  const cx = (b.x0 + b.x1) / 2, cy = (b.y0 + b.y1) / 2;
  (TOUR[id] || []).forEach((a, i) => {
    let x = b.x0 + (a[2] - g[0]) / (g[2] - g[0]) * w, y = b.y0 + (g[3] - a[1]) / (g[3] - g[1]) * h;
    if (!a[4] && mpath.isPointInFill) {
      for (let k = 0; k < 30; k++) {
        let ok = true;
        try { const pt = _tourM.createSVGPoint(); pt.x = x; pt.y = y; ok = mpath.isPointInFill(pt); } catch (e) { ok = true; }
        if (ok) break;
        x += (cx - x) * 0.1; y += (cy - y) * 0.1;
      }
    }
    out.push({ i: i, n: a[0], lat: a[1], lon: a[2], d: a[3], isl: !!a[4], x: x, y: y });
  });
  for (let pass = 0; pass < 12; pass++) {
    for (let i = 0; i < out.length; i++) for (let j = i + 1; j < out.length; j++) {
      const A = out[i], B = out[j]; let dx = B.x - A.x, dy = B.y - A.y, d = Math.hypot(dx, dy);
      const mn = r * 2.4;
      if (d < mn) { if (d < 0.01) { dx = 1; dy = 0.3; d = 1.04; } const k = (mn - d) / 2 / d; A.x -= dx * k; A.y -= dy * k; B.x += dx * k; B.y += dy * k; }
    }
  }
