  const h = { type: "hero", def: def, team: team, lane: lane, player: !!player, name: name, x: b.x + (team ? -60 : 60), y: b.y + (lane - 1) * 80, hp: 1, max: 0, lv: 1, xp: 0, dir: team ? Math.PI : 0, atkT: 0, cd: [0, 0, 0], dead: false, respT: 0, r: 22, slow: 0, stun: 0, buff: 0, hitT: 0, kills: 0, deaths: 0, retreat: false, path: lgLanePath(lane, team), pi: 1, aggro: team ? [260, 340, 400][LG.sel.diff] : 340, aiT: Math.random(), ult: 0, mv: 0, it: [], gold: 150, spdM: 1, red: 1, shield: 0, shT: 0, dash: 0, qbuff: 0, dT: 0, inBush: false, pal: 0, buyT: Math.random() * 3, shopT: 0, lastShop: 0 };
