  const cx = curXp(), ri = myRank(), next = RANKS[ri + 1];
  { const sd = mySid(), lg = sd ? logoOf(sd) : ""; $("meIns").innerHTML = (lg ? '<span class="crestbk" style="background-image:url(' + lg + ')"></span>' : "") + insignia(ri, 34); }
