  const cur = el("div", { class: "card" });
  const row = el("div", { class: "row", style: "gap:16px" });
  const ins = el("span"); ins.innerHTML = insignia(ri, 64);
  const tx = el("div");
  tx.append(el("div", { class: "tagline" }, "Pangkat semasa"), el("div", { style: "font-family:var(--font-display);font-size:28px;color:var(--amber)" }, RANKS[ri].n), el("div", { class: "muted" }, Math.round(cx) + " mata" + (next ? ". " + Math.ceil(next.xp - cx) + " mata lagi untuk " + next.n + "." : ". Pangkat tertinggi dicapai.")));
  row.append(ins, tx); cur.appendChild(row);
  box.appendChild(cur);
  const idle = idleDays(P.la, Date.now()), lost = Math.round(P.xp - cx);
  const info = [];
  if (raw > ri && Net.stand) info.push("Mata anda cukup untuk " + RANKS[raw].n + ", tetapi pangkat itu dihadkan kepada " + seatsOf(raw, Net.stand.n) + " tempat. Kedudukan anda ialah #" + Net.stand.pos + " daripada " + Net.stand.n + ". Main lebih banyak untuk merampasnya.");
  if (lost > 0) info.push("Anda tidak aktif " + idle + " hari. Mata telah susut " + lost + ".");
  else info.push("Mata mula susut selepas " + DECAY_GRACE + " hari tidak bermain (kadar " + (decayRate(P.ad) * 100).toFixed(1) + "% sehari; makin banyak hari anda aktif, makin perlahan).");
