  for (let i = 0; i < 3; i++) g += '<rect x="' + (25 + i * 10.5) + '" y="47" width="9" height="9" fill="' + sh(a.uni, -0.62) + '"/><rect x="' + (25 + i * 10.5) + '" y="47" width="9" height="1.6" fill="#fff" opacity=".18"/>';
  g += '<rect x="18" y="60" width="44" height="4" fill="#2a2418"/><rect x="37" y="59.4" width="6" height="5.2" fill="' + gold + '"/>';
  g += '<path d="M12 31l8-5h7v8H12z" fill="' + sh(a.uni, 0.12) + '"/><path d="M68 31l-8-5h-7v8h15z" fill="' + sh(a.uni, -0.2) + '"/>';
  g += '<rect x="8" y="30" width="11" height="32" fill="url(#' + id + 'u)"/><rect x="61" y="30" width="11" height="32" fill="url(#' + id + 'u)"/>';
