  g += '<rect x="34.5" y="17" width="4" height="2.2" fill="#15171a"/><rect x="41.5" y="17" width="4" height="2.2" fill="#15171a"/><rect x="36" y="23.6" width="8" height="1.2" fill="#8a5f3e"/>';
