  { const sm = /^s(\d+)([pe])$/.exec(acc || ""); if (sm) { const sc = seasonCol(+sm[1]); if (sm[2] === "p") g += '<rect x="45" y="34" width="5" height="8" fill="' + sc + '"/><circle cx="47.5" cy="45" r="4.4" fill="' + sc + '" stroke="#fff" stroke-width="1"/>'; else g += '<rect x="14" y="27" width="12" height="5" fill="' + sc + '"/><rect x="54" y="27" width="12" height="5" fill="' + sc + '"/><rect x="14" y="27" width="12" height="1.4" fill="#fff"/><rect x="54" y="27" width="12" height="1.4" fill="#fff"/>'; } }
