/* ---------- Muzik latar dijana (berubah apabila pertempuran) ---------- */
const MUS = { bus: null, timer: 0, t: 0, step: 0, heat: 0, run: false, nb: null };
const MUS_ROOT = [55, 43.65, 49, 41.2], MUS_EIGHTH = 0.3;
let LOWT = 0, HITSRC = null;
function musTone(t, f, d, type, v, lp) {
  const ac = AUD.ctx, o = ac.createOscillator(), g = ac.createGain(), fl = ac.createBiquadFilter();
  fl.type = "lowpass"; fl.frequency.value = lp || 1200; o.type = type; o.frequency.setValueAtTime(f, t);
  g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(v, t + 0.03); g.gain.exponentialRampToValueAtTime(0.0001, t + d);
  o.connect(fl); fl.connect(g); g.connect(MUS.bus); o.start(t); o.stop(t + d + 0.05);
}
function musNoise(t, d, hp, v) {
  const ac = AUD.ctx, s = ac.createBufferSource(), f = ac.createBiquadFilter(), g = ac.createGain();
  s.buffer = MUS.nb; f.type = "highpass"; f.frequency.value = hp;
  g.gain.setValueAtTime(v, t); g.gain.exponentialRampToValueAtTime(0.0001, t + d);
  s.connect(f); f.connect(g); g.connect(MUS.bus); s.start(t, Math.random() * 0.5, d + 0.05);
}
function musStep(t, st) {
  const ac = AUD.ctx, r = MUS_ROOT[(st >> 4) & 3], p = st & 15, act = MUS.heat > 0;
  if (p === 0 || p === 8 || (act && (p === 4 || p === 12))) {
    const o = ac.createOscillator(), g = ac.createGain();
    o.type = "sine"; o.frequency.setValueAtTime(120, t); o.frequency.exponentialRampToValueAtTime(42, t + 0.14);
    g.gain.setValueAtTime(0.6, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.18);
    o.connect(g); g.connect(MUS.bus); o.start(t); o.stop(t + 0.2);
  }
  if (p === 0 || p === 2 || p === 3 || p === 6 || p === 8 || p === 10 || p === 11 || p === 14) musTone(t, r * (p === 6 || p === 14 ? 2 : 1), 0.22, "sawtooth", 0.16, 420);
  if (p === 0) [1, 1.1892, 1.4983].forEach((m) => musTone(t, r * 4 * m, MUS_EIGHTH * 15, "triangle", 0.04, 900));
  if (act) {
    if (p === 4 || p === 12) musNoise(t, 0.14, 1400, 0.3);
    if (p % 2 === 0) musNoise(t, 0.035, 6500, 0.1);
    if ((p & 3) === 3) musTone(t, r * 8 * [1, 1.1892, 1.4983, 2][(p >> 2) & 3], 0.16, "square", 0.045, 1800);
  }
}
function musSched() {
  const ac = AUD.ctx; if (!ac || !MUS.bus) return;
  try {
    if (MUS.t < ac.currentTime - 0.3) MUS.t = ac.currentTime + 0.05;
    while (MUS.t < ac.currentTime + 0.5) { musStep(MUS.t, MUS.step); MUS.t += MUS_EIGHTH; MUS.step = (MUS.step + 1) & 63; }
  } catch (e) { /* abaikan */ }
}
function musStart() {
  audioInit(); const ac = AUD.ctx; if (!ac || MUS.run) return;
  try {
    const bus = ac.createGain(); bus.gain.value = 0; bus.connect(ac.destination);
    const nb = ac.createBuffer(1, ac.sampleRate >> 1, ac.sampleRate), d = nb.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
    MUS.nb = nb; MUS.bus = bus; MUS.t = ac.currentTime + 0.1; MUS.step = 0; MUS.heat = 0; MUS.run = true;
    musSched(); MUS.timer = setInterval(musSched, 150);
  } catch (e) { MUS.run = false; MUS.bus = null; }
}
function musStop() {
  clearInterval(MUS.timer); MUS.run = false;
  const b = MUS.bus; MUS.bus = null;
  if (b) { try { b.gain.setTargetAtTime(0, AUD.ctx.currentTime, 0.2); } catch (e) { /* abaikan */ } setTimeout(() => { try { b.disconnect(); } catch (e) { /* abaikan */ } }, 900); }
  const lh = $("lowhp"); if (lh) lh.classList.remove("on");
}
function musApply() { if (MUS.bus) { try { MUS.bus.gain.setTargetAtTime(musVol(), AUD.ctx.currentTime, 0.1); } catch (e) { /* abaikan */ } } }
function musVol() { return SET.mus * 0.3 * (S.inQuiz || S.paused ? 0.35 : 1); }
function musTick(dt) {
  if (MUS.bus) { MUS.heat = Math.max(0, MUS.heat - dt); try { MUS.bus.gain.setTargetAtTime(musVol(), AUD.ctx.currentTime, 0.3); } catch (e) { /* abaikan */ } }
  const low = S.hp < 30 && S.deadT <= 0 && S.running && !S.over;
  const lh = $("lowhp"); if (lh && lh.classList.contains("on") !== low) lh.classList.toggle("on", low);
  if (low && !S.paused && !S.inQuiz) { LOWT -= dt; if (LOWT <= 0) { LOWT = 0.9; sfxHeart(); } }
}

