  const n = TOUCH ? 4 : 8, r = Math.random;
  for (let i = 0; i < n; i++) fxEmit("blood", pt.x, pt.y, pt.z, (r() - 0.5) * 3.2, r() * 2.2 + 0.4, (r() - 0.5) * 3.2, 0.45 + r() * 0.3, 0.07, 0, 14);
