    if (!TOUCH) { muzzleL = new T3.PointLight(srgb(0xffb868), 0, 14, 2); muzzleL.position.set(0, 0.04, -0.7); gun.add(muzzleL); }
    const mk = (geo, mat, x, y, z, rx) => { const m = new T3.Mesh(geo, mat); m.position.set(x, y, z); if (rx) m.rotation.x = rx; m.visible = false; gun.add(m); return m; };
