  const bodyM = new T3.MeshLambertMaterial({ color: srgb(0x2b2f36) }), bladeM = new T3.MeshLambertMaterial({ color: srgb(0xaab2bb) }), ledM = new T3.MeshBasicMaterial({ color: srgb(0xff2a2a) });
