  const d = { isBot: true, isDrone: true, hp: 30, max: 30, dead: false, deadT: 0, x: x, y: y, z: z, vy: 0, g: g, parts: parts, mats: [bodyM, bladeM], rotors: rotors, st: 0, t: 0, stalk: 4 + Math.random() * 3, a: Math.random() * 6.28, beepT: 0, losT: 0, flashT: 0 };
