  const m = new T3.Mesh(new T3.CylinderGeometry(r1, r0, L, 9), mat);
  m.position.copy(A).addScaledVector(d, 0.5); m.quaternion.setFromUnitVectors(new T3.Vector3(0, 1, 0), d.normalize());
