      const a = Math.random() * 6.28, r = 55 + Math.random() * 25;
      const x = clamp(pl.x + Math.cos(a) * r, -HALF + 6, HALF - 6), z = clamp(pl.z + Math.sin(a) * r, -HALF + 6, HALF - 6);
      if (freeSpot(x, z, 1.5)) p = { x: x, z: z };
