    let mx = dx / dist, mz = dz / dist;
    if (b.side) { const c = Math.cos(b.side * 1.1), s = Math.sin(b.side * 1.1); const nx = mx * c - mz * s, nz = mx * s + mz * c; mx = nx; mz = nz; b.sideT -= dt; if (b.sideT <= 0) b.side = 0; }
    const sp = dist < 40 ? 7.6 : 6.2;
    if (dist > 1.3) {
      const bx = b.x, bz = b.z, pos = { x: b.x + mx * sp * dt, z: b.z + mz * sp * dt };
      pushOut(pos, 0.5, 0);
      const moved = Math.hypot(pos.x - bx, pos.z - bz);
      if (moved < sp * dt * 0.35) { b.stuck += dt; if (b.stuck > 0.25) { b.stuck = 0; b.side = Math.random() < 0.5 ? 1 : -1; b.sideT = 0.7; } } else b.stuck = 0;
      b.x = clamp(pos.x, -HALF + 2, HALF - 2); b.z = clamp(pos.z, -HALF + 2, HALF - 2); moving = true;
    }
