function buildDepots(rnd) {
  depots = [];
  if (!M || M.exam) return;
  for (let k = 0; k < 2; k++) {
    let p = null;
    for (let i = 0; i < 40 && !p; i++) {
      const c = tSpot(rnd, 8.5, 24);
      if (c && c.z < HALF - 22 && depots.every((d) => Math.hypot(d.x - c.x, d.z - c.z) > 70)) p = c;
    }
    if (!p) continue;
    try { makeDepot(p.x, p.z); depots.push({ x: p.x, z: p.z, w: DEPOT_W, d: DEPOT_D }); } catch (e) { /* abaikan */ }
  }
}
function nearDepot() {
  for (const d of depots) if (Math.abs(pl.x - d.x) < d.w / 2 - 0.3 && pl.z > d.z - d.d / 2 && pl.z < d.z + d.d / 2 + 1.8 && pl.y < 1.5) return d;
  return null;
}
