function buildWorld(rnd) {
  themePal();
  const R = (a, b) => a + rnd() * (b - a);
  const PK = (a) => a[Math.floor(rnd() * a.length)];
  shapes();
  BLDG = []; ROADS = [];
  // pulau heksagon (bahagian atas rumput; tebing di buildEnv)
  const ground = new T3.Mesh(new T3.CylinderGeometry(215, 215, 0.6, 6, 1, false), [lam(0x8a6a4a), new T3.MeshLambertMaterial({ map: groundTex }), lam(0x8a6a4a)]);
  ground.position.y = -0.3; themeGround = ground;
  missionG.add(ground);
  const fence = 0x6f7a5a;
  addBox(0, -HALF - 3, HALF * 2 + 12, 1.6, 0.8, fence);
  addBox(0, HALF + 3, HALF * 2 + 12, 1.6, 0.8, fence);
  addBox(-HALF - 3, 0, 0.8, 1.6, HALF * 2 + 12, fence);
  addBox(HALF + 3, 0, 0.8, 1.6, HALF * 2 + 12, fence);
  let n = 0, guard = 0;
  while (n < 12 && guard++ < 400) {
    const x = R(-HALF + 15, HALF - 15), z = R(-HALF + 15, HALF - 15);
    const w = R(6, 10), d = R(6, 9), h = 3.4;
    if (Math.hypot(x, z) < 10 || !freeSpot(x, z, 9)) continue;
    const wc = n < 2 ? 0xf6f1e3 : PK(PAL.wall);
    addBox(x, z, w, h, d, wc); BLDG.push({ x: x, z: z, w: w, d: d });
    if (n < 2) surauDecor(x, z, w, d, h); else houseDecor(x, z, w, d, h, wc, rnd);
    n++;
  }
  planRoads();
  n = 0; guard = 0;
  while (n < 6 && guard++ < 300) {
    const x = R(-HALF + 10, HALF - 10), z = R(-HALF + 10, HALF - 10), flip = rnd() < 0.5;
    if (!freeSpot(x, z, 5) || onRoad(x, z, 3)) continue;
    addBox(x, z, flip ? 2.4 : 6, 2.6, flip ? 6 : 2.4, PK(PAL.crate));
    n++;
  }
  n = 0; guard = 0;
  while (n < 22 && guard++ < 500) {
    const x = R(-HALF + 8, HALF - 8), z = R(-HALF + 8, HALF - 8), flip = rnd() < 0.5;
    if (!freeSpot(x, z, 2.5) || onRoad(x, z, 2.6)) continue;
    addBox(x, z, flip ? 0.9 : 3.4, 1, flip ? 3.4 : 0.9, 0xcdb87a);
    n++;
  }
  n = 0; guard = 0;
  while (n < 85 && guard++ < 800) {
    const x = R(-HALF + 4, HALF - 4), z = R(-HALF + 4, HALF - 4);
    if (!freeSpot(x, z, 2) || onRoad(x, z, 2.4)) continue;
    const s = R(0.9, 1.4), palm = rnd() < 0.35;
    const g = palm ? treePalm(x, z, s * 0.9, rnd) : treeRound(x, z, s, rnd);
    obstacles.push({ minx: x - 0.45, maxx: x + 0.45, minz: z - 0.45, maxz: z + 0.45, h: 9 });
    const hit = new T3.Mesh(new T3.CylinderGeometry(0.3, 0.3, 3, 5), new T3.MeshBasicMaterial({ visible: false }));
    hit.position.set(x, 1.5, z); missionG.add(hit); solids.push(hit);
    n++;
  }
  themeApply(rnd);
  buildDepots(rnd);
}
/* hiasan tidak berlanggar: semak, batu, pokok luar pagar, tebing, air, awan, pulau kecil */
let envG = null, waterTex = null, clouds = [], sunDisc = null, waterM = null, hemiL = null, sunGlow = null, hazeM = null;
function buildEnv(seed) {
  const dr = rng(seed ^ 0x51ed1234), R = (a, b) => a + dr() * (b - a), G = shapes();
  envG = new T3.Group(); missionG.add(envG);
  const playDecor = decorG; decorG = new T3.Group(); envG.add(decorG); const envDecor = decorG;
  // semak dan batu di dalam kawasan main
  for (let i = 0, g = 0; i < 70 && g < 400; g++) { const x = R(-HALF + 3, HALF - 3), z = R(-HALF + 3, HALF - 3); if (!freeSpot(x, z, 1.6)) continue; bushAt(x, z, R(0.8, 1.5), dr); i++; }
  for (let i = 0, g = 0; i < 28 && g < 300; g++) { const x = R(-HALF + 3, HALF - 3), z = R(-HALF + 3, HALF - 3); if (!freeSpot(x, z, 1.5)) continue; rockAt(x, z, R(0.8, 2)); i++; }
  // pokok di luar pagar
  const nOut = TOUCH ? 40 : 90;
  for (let i = 0, g = 0; i < nOut && g < 600; g++) {
    const x = R(-205, 205), z = R(-205, 205);
    if (Math.abs(x) < HALF + 9 && Math.abs(z) < HALF + 9) continue;
    if (Math.abs(x) * 0.866 + Math.abs(z) * 0.5 > 196 || Math.abs(z) > 196) continue;
    (dr() < 0.5 ? treePalm : treeRound)(x, z, R(1, 1.6), dr); i++;
  }
  // pasir, tebing, buih
  const sand = new T3.Mesh(new T3.CylinderGeometry(224, 224, 0.5, 6, 1, false), lam(0xe8d49a)); sand.position.y = -0.38; envG.add(sand);
  const cliff = new T3.Mesh(new T3.CylinderGeometry(222, 204, 14, 6, 1, true), lamF(0x8a6a4a)); cliff.position.y = -7; envG.add(cliff);
  const foam = new T3.Mesh(new T3.CylinderGeometry(232, 232, 0.1, 6, 1, false), new T3.MeshBasicMaterial({ color: srgb(0xffffff), transparent: true, opacity: 0.55, depthWrite: false })); foam.position.y = -3.4; envG.add(foam);
  // air
  waterTex = makeTex(128, 128, (g, w, h) => {
    g.fillStyle = "#3fa9cc"; g.fillRect(0, 0, w, h);
    g.strokeStyle = "rgba(255,255,255,.35)"; g.lineWidth = 2;
    for (let i = 0; i < 14; i++) { const x = Math.random() * w, y = Math.random() * h; g.beginPath(); g.moveTo(x, y); g.quadraticCurveTo(x + 10, y - 4, x + 22, y); g.stroke(); }
  }, 70);
  waterM = new T3.MeshLambertMaterial({ map: waterTex, color: srgb(0xffffff), transparent: true, opacity: 0.9, emissive: srgb(0x0b2a3a) });
  const water = new T3.Mesh(new T3.PlaneGeometry(1500, 1500), waterM);
  water.rotation.x = -Math.PI / 2; water.position.y = -3.6; envG.add(water);
  // pulau heksagon kecil di kejauhan
  const nIs = TOUCH ? 4 : 8;
  for (let i = 0; i < nIs; i++) {
    const a = (i / nIs) * Math.PI * 2 + R(-0.2, 0.2), d = R(285, 335), x = Math.cos(a) * d, z = Math.sin(a) * d, r = R(16, 34);
    const top = new T3.Mesh(new T3.CylinderGeometry(r, r * 0.8, 16, 6, 1, false), [lamF(0x8a6a4a), lam(0x7bb04a), lamF(0x8a6a4a)]);
    top.position.set(x, -8, z); envG.add(top);
    for (let k = 0; k < 4; k++) { const ox = R(-r * 0.6, r * 0.6), oz = R(-r * 0.5, r * 0.5); (dr() < 0.5 ? treePalm : treeRound)(x + ox, z + oz, R(0.9, 1.5), dr); }
  }
  // awan dan matahari
  clouds = [];
  const cm = new T3.MeshBasicMaterial({ color: srgb(0xffffff), transparent: true, opacity: 0.92, depthWrite: false, fog: false });
  const nC = TOUCH ? 6 : 12;
  for (let i = 0; i < nC; i++) {
    const c = new T3.Group();
    for (let k = 0; k < 4; k++) put(G.bush, cm, k * 7 - 10, R(-1, 2), R(-3, 3), R(6, 10), R(3, 5), R(5, 8), c);
    c.position.set(R(-320, 320), R(75, 120), R(-320, 320)); c.userData.mat = cm;
    envG.add(c); clouds.push(c);
  }
  sunDisc = new T3.Mesh(new T3.SphereGeometry(16, 16, 10), new T3.MeshBasicMaterial({ color: srgb(0xfff4c8), fog: false }));
  envG.add(sunDisc);
  try {
    sunGlow = new T3.Sprite(new T3.SpriteMaterial({ map: glowTex(), color: srgb(0xfff0cf), transparent: true, opacity: 0.5, blending: T3.AdditiveBlending, depthWrite: false, fog: false }));
    sunGlow.scale.set(300, 300, 1); sunGlow.renderOrder = -5; envG.add(sunGlow);
    hazeM = new T3.Mesh(new T3.CylinderGeometry(300, 300, 64, 28, 1, true), new T3.MeshBasicMaterial({ map: hazeTex(), color: srgb(0xcfe6f2), transparent: true, depthWrite: false, side: T3.BackSide, fog: false }));
    hazeM.renderOrder = 4; hazeM.frustumCulled = false; envG.add(hazeM);
    if (GFX.lvl >= 2) { hazeM.visible = false; sunGlow.visible = false; }
  } catch (e) { sunGlow = null; hazeM = null; }
  // semua hiasan tidak menerima/tidak membentuk bayang kecuali pokok
  envG.traverse((m) => { if (m.isMesh) { m.castShadow = false; m.receiveShadow = false; } });

  // rumput, bunga dan burung (ringan, satu panggilan lukis setiap satu)
  try {
    envFx = new T3.Group(); envG.add(envFx);
    const nG = TOUCH ? 450 : 1100, dum = new T3.Object3D();
    const gr = new T3.InstancedMesh(new T3.ConeGeometry(0.07, 0.55, 3), new T3.MeshLambertMaterial({ color: srgb(0xffffff) }), nG);
    gr.frustumCulled = false;
    for (let i = 0; i < nG; i++) {
      dum.position.set(R(-HALF, HALF), 0.25, R(-HALF, HALF)); dum.rotation.set(R(-0.25, 0.25), R(0, 6.28), R(-0.25, 0.25));
      const sc = R(0.7, 1.7); dum.scale.set(sc, sc * R(0.8, 1.5), sc); dum.updateMatrix(); gr.setMatrixAt(i, dum.matrix);
      if (gr.setColorAt) gr.setColorAt(i, srgb([0x4f8a2a, 0x62a032, 0x7aa83e, 0x86b34a][i & 3]));
    }
    envFx.add(gr);
    const nF = TOUCH ? 60 : 160;
    const fl = new T3.InstancedMesh(new T3.SphereGeometry(0.09, 5, 4), new T3.MeshLambertMaterial({ color: srgb(0xffffff) }), nF);
    fl.frustumCulled = false;
    for (let i = 0; i < nF; i++) {
      dum.position.set(R(-HALF, HALF), 0.22, R(-HALF, HALF)); dum.rotation.set(0, 0, 0); dum.scale.set(1, 1, 1); dum.updateMatrix(); fl.setMatrixAt(i, dum.matrix);
      if (fl.setColorAt) fl.setColorAt(i, srgb([0xffffff, 0xffd84a, 0xff6f91, 0xb48cff][i & 3]));
    }
    envFx.add(fl);
    birds = [];
    const bm = lam(0x2b2b2b);
    for (let i = 0; i < (TOUCH ? 3 : 6); i++) {
      const b = new T3.Group(), wl = new T3.Group(), wr = new T3.Group();
      b.add(new T3.Mesh(new T3.BoxGeometry(0.16, 0.12, 0.45), bm));
      const w1 = new T3.Mesh(new T3.BoxGeometry(0.6, 0.02, 0.2), bm); w1.position.x = -0.3; wl.add(w1);
      const w2 = new T3.Mesh(new T3.BoxGeometry(0.6, 0.02, 0.2), bm); w2.position.x = 0.3; wr.add(w2);
      b.add(wl, wr);
      b.userData = { wl: wl, wr: wr, a: R(0, 6.28), rad: R(40, 110), y: R(32, 58), sp: R(0.12, 0.22), ph: R(0, 6) };
      envFx.add(b); birds.push(b);
    }
  } catch (e) { envFx = null; birds = []; }
  mergeStatic(playDecor, true); mergeStatic(envDecor, false);
  decorG = null;
}

