const WX_ORDER = ["auto", "cerah", "subuh", "senja", "hujan", "kabus"];
const WX_NAMA = { auto: "Auto (ikut misi)", cerah: "Cerah", subuh: "Subuh", senja: "Senja", hujan: "Hujan", kabus: "Kabus pagi" };
const WXK = ["top", "hor", "low", "fog", "sun", "si", "el", "hs", "hg", "hi", "ex", "cloud", "fn", "ff", "gl", "co", "dv"];
const wxPal = (a) => { const o = {}; WXK.forEach((k, i) => { o[k] = a[i]; }); return o; };
const WX = {
  cerah: { day: wxPal([0x3d86d8, 0xcfe6f2, 0x9bb98a, 0xcfe6f2, 0xfff0cf, 1.25, 62, 0xbfdcff, 0x6d8a45, 0.62, 1.15, 0xffffff, 90, 340, 0.45, 0.92, 1]), eve: wxPal([0x4a5fa8, 0xffb677, 0xb98a6a, 0xf0b58a, 0xff9a4a, 1.3, 13, 0xffc89a, 0x7a6a4a, 0.55, 1.05, 0xffd2b0, 80, 320, 0.85, 0.92, 1]) },
  subuh: { day: wxPal([0x2b3a78, 0xffa88a, 0x8a7a8a, 0xe8b0a0, 0xffb070, 0.9, 7, 0xffd0c0, 0x6a6a5a, 0.55, 1.0, 0xffc0a8, 45, 260, 0.9, 0.95, 1]), eve: wxPal([0x4f8ad8, 0xffe0c0, 0xa8b890, 0xf6dcc0, 0xffe0b0, 1.15, 30, 0xdce8ff, 0x72904a, 0.68, 1.1, 0xfff0e0, 80, 320, 0.6, 0.92, 1]) },
  senja: { day: wxPal([0x3a3f8a, 0xff8a4a, 0x9a6a5a, 0xe89a6a, 0xff7a30, 1.3, 9, 0xffb080, 0x6a5a4a, 0.52, 1.05, 0xff9a70, 70, 300, 1.0, 0.95, 1]), eve: wxPal([0x1e2250, 0xd8506a, 0x4a3a4a, 0x8a4a5a, 0xff5a3a, 0.9, 3, 0x8a6aa0, 0x3a3a3a, 0.42, 1.0, 0xb05a6a, 55, 260, 0.9, 0.95, 1]) },
  hujan: { rain: 1, day: wxPal([0x5a6672, 0x8e9aa4, 0x6f7a6a, 0x8a949c, 0xb8c4d0, 0.5, 50, 0x9aa8b4, 0x4a5a40, 0.72, 1.05, 0x7a858f, 28, 190, 0, 1, 0]), eve: wxPal([0x3e4852, 0x6a7680, 0x55604f, 0x646e76, 0x9aa8b8, 0.35, 40, 0x7a8894, 0x3a4a34, 0.58, 1.0, 0x555f68, 22, 170, 0, 1, 0]) },
  kabus: { day: wxPal([0xaab8c4, 0xdfe6e8, 0xb5c0b0, 0xdde4e6, 0xfff4e0, 0.7, 28, 0xe6eef2, 0x7a8a6a, 0.85, 1.1, 0xf2f4f4, 10, 150, 0.25, 0.95, 0]), eve: wxPal([0x98a6b4, 0xe8e0d8, 0xa8b0a0, 0xd8d4d0, 0xffe6c0, 0.75, 18, 0xe8e0dc, 0x6a7a5a, 0.78, 1.08, 0xeee8e4, 14, 170, 0.35, 0.95, 0]) }
};
const TOD = { day: WX.cerah.day, eve: WX.cerah.eve, wx: "cerah", flash: 0, thT: 18, hi: 0.62 };
const todCol = (a, b, k) => { const c = srgb(a); c.lerp(srgb(b), k); return c; };
const todNum = (a, b, k) => a + (b - a) * k;
function wxResolve(name, seed, exam) {
  if (name && name !== "auto" && WX[name]) return name;
  if (exam) return "cerah";
  const r = rng(((seed | 0) ^ 0x3c1f9e) >>> 0)();
  return r < 0.4 ? "cerah" : r < 0.6 ? "subuh" : r < 0.78 ? "senja" : r < 0.9 ? "hujan" : "kabus";
}
function wxSet(name, k) {
  const w = WX[name] || WX.cerah; TOD.wx = WX[name] ? name : "cerah";
  TOD.day = w.day; TOD.eve = w.eve; TOD.flash = 0; TOD.thT = 12 + Math.random() * 14;
  try { rainSet(!!w.rain && GFX.lvl < 3); } catch (e) { /* abaikan */ }
  applyTOD(k == null ? clamp((TOD.k0 || 0) + (S.time || 0) / 480, 0, 1) : k);
}
function applyTOD(k) {
  const D = TOD.day, E = TOD.eve;
  try {
    const hor = todCol(D.hor, E.hor, k), fog = todCol(D.fog, E.fog, k);
    if (skyM && skyM.userData.paint) skyM.userData.paint(todCol(D.top, E.top, k), hor, todCol(D.low, E.low, k));
    if (scene.fog) { scene.fog.color.copy(fog); scene.fog.near = todNum(D.fn, E.fn, k); scene.fog.far = todNum(D.ff, E.ff, k); }
    scene.background = fog;
    if (sunL) { sunL.color.copy(todCol(D.sun, E.sun, k)); sunL.intensity = todNum(D.si, E.si, k); }
    if (hemiL) { hemiL.color.copy(todCol(D.hs, E.hs, k)); hemiL.groundColor.copy(todCol(D.hg, E.hg, k)); TOD.hi = todNum(D.hi, E.hi, k); hemiL.intensity = TOD.hi + (TOD.flash > 0 ? TOD.flash * 1.4 : 0); }
    if (renderer) renderer.toneMappingExposure = todNum(D.ex, E.ex, k);
    const el = todNum(D.el, E.el, k) * Math.PI / 180, az = 0.6;
    TOD.dir = { x: Math.cos(el) * Math.cos(az), y: Math.sin(el), z: Math.cos(el) * Math.sin(az) };
    if (sunDisc && sunDisc.material.color) { sunDisc.material.color.copy(todCol(0xfff4c8, 0xffa860, k)); sunDisc.visible = todNum(D.dv, E.dv, k) > 0.5; }
    if (sunGlow) { sunGlow.material.color.copy(todCol(D.sun, E.sun, k)); sunGlow.material.opacity = todNum(D.gl, E.gl, k); }
    if (hazeM && hazeM.material) hazeM.material.color.copy(fog);
    if (waterM) waterM.color.copy(todCol(0xffffff, 0xffc9a0, k));
    for (const c of clouds) if (c.userData.mat) { c.userData.mat.color.copy(todCol(D.cloud, E.cloud, k)); c.userData.mat.opacity = todNum(D.co, E.co, k); }
  } catch (e) { /* abaikan jika API tidak disokong */ }
}
