function hazeTex() { return _haze || (_haze = makeTex(8, 128, (g, w, h) => { const r = g.createLinearGradient(0, 0, 0, h); r.addColorStop(0, "rgba(255,255,255,0)"); r.addColorStop(0.5, "rgba(255,255,255,.22)"); r.addColorStop(1, "rgba(255,255,255,.92)"); g.fillStyle = r; g.fillRect(0, 0, w, h); }, 0)); }
