  const tank = new T3.Mesh(new T3.SphereGeometry(1, 14, 10), pl1); tank.position.set(0, 1.16, -0.36); tank.scale.set(0.2, 0.15, 0.42); body.add(tank);
  bx(0.27, 0.1, 0.88, blk, [0, 1.13, 0.42], [-0.03, 0, 0]);
  bx(0.2, 0.03, 0.55, pl1, [0, 1.2, 1.08], [-0.3, 0, 0]);
  /* peredam hentak, ekzos */
  limb3([0, 1.0, 0.4], [0, 0.6, 0.62], 0.045, 0.04, yel, body);
  limb3([0.14, 0.78, -0.22], [0.2, 0.7, 0.3], 0.045, 0.045, met, body);
  limb3([0.2, 0.7, 0.3], [0.21, 0.92, 0.75], 0.045, 0.06, met, body);
  limb3([0.21, 0.92, 0.7], [0.21, 1.02, 1.3], 0.075, 0.075, met, body);
  cy(0.078, 0.078, 0.03, blk, [0.21, 1.03, 1.31], [1.45, 0, 0]);
  /* penunggang askar */
  const rider = new T3.Group(); rider.visible = false; body.add(rider);
  const tor = new T3.Mesh(new T3.BoxGeometry(0.42, 0.56, 0.26), sk); tor.position.set(0, 1.58, 0.28); tor.rotation.x = -0.42; rider.add(tor);
  const pack = new T3.Mesh(new T3.BoxGeometry(0.34, 0.4, 0.14), sk2); pack.position.set(0, 1.58, 0.45); pack.rotation.x = -0.42; rider.add(pack);
  const hd = new T3.Mesh(new T3.SphereGeometry(0.15, 12, 9), skin); hd.position.set(0, 1.98, 0.02); rider.add(hd);
  const hel = new T3.Mesh(new T3.SphereGeometry(0.175, 12, 9, 0, Math.PI * 2, 0, Math.PI * 0.55), sk2); hel.position.set(0, 2.0, 0.03); rider.add(hel);
  for (const sx of [-1, 1]) {
    limb3([sx * 0.26, 1.78, 0.2], [sx * 0.34, 1.52, -0.3], 0.07, 0.06, sk, rider);
    limb3([sx * 0.34, 1.52, -0.3], [sx * 0.37, 1.34, -0.8], 0.06, 0.05, sk, rider);
    limb3([sx * 0.15, 1.2, 0.6], [sx * 0.27, 0.98, 0.15], 0.1, 0.075, sk2, rider);
    limb3([sx * 0.27, 0.98, 0.15], [sx * 0.29, 0.66, 0.2], 0.075, 0.065, sk2, rider);
    const bt = new T3.Mesh(new T3.BoxGeometry(0.11, 0.09, 0.26), blk); bt.position.set(sx * 0.29, 0.6, 0.12); rider.add(bt);
  }
  /* senapang penunggang: muncung ialah titik asal peluru semasa menembak di atas motor */
  const rf = new T3.Group(); rf.position.set(0.24, 1.5, -0.62); rider.add(rf);
  const rfa = new T3.Mesh(new T3.BoxGeometry(0.08, 0.11, 0.62), blk); rf.add(rfa);
  const rfb = new T3.Mesh(new T3.BoxGeometry(0.05, 0.05, 0.38), eng); rfb.position.set(0, 0.015, -0.48); rf.add(rfb);
  const rfc = new T3.Mesh(new T3.BoxGeometry(0.06, 0.13, 0.1), blk); rfc.position.set(0, -0.1, 0.1); rf.add(rfc);
  const muz = new T3.Object3D(); muz.position.set(0, 0.015, -0.7); rf.add(muz);
  pivot.position.set(0, 0.44, 1.0); body.position.set(0, -0.44, -1.0); // paksi roda belakang untuk wheelie
  pivot.add(body);
  const turret = new T3.Group();
  const beam = new T3.Mesh(new T3.CylinderGeometry(0.3, 0.3, 14, 10, 1, true), new T3.MeshBasicMaterial({ color: srgb(0x5ec8ff), transparent: true, opacity: 0.35, depthWrite: false, side: T3.DoubleSide, fog: false }));
  beam.position.y = 7;
  g.add(pivot, turret, beam);
  g.rotation.order = "YXZ"; g.position.set(x, 0, z); g.rotation.y = yaw;
  const ob = { minx: x - 1.4, maxx: x + 1.4, minz: z - 1.4, maxz: z + 1.4, h: 1.3 };
  obstacles.push(ob);
