    if (!bk) t.whOn = 0;
    if (bk && sp > 4 && Math.random() < dt * 22) { const r = Math.random; try { fxEmit("dust", t.x + Math.sin(t.yaw) * 1.1, 0.25, t.z + Math.cos(t.yaw) * 1.1, (r() - 0.5) * 1.4, 0.8, (r() - 0.5) * 1.4, 0.8, 0.3, 2.4, -0.3); } catch (e) { /* abaikan */ } }
