  const alive = bots.filter((b) => !b.dead && !b.isDog && !b.isSniper && !b.isBoss && !b.isDrone && !b.isApc && !b.isHeli).length;
  const cap = (M.bots | 0) + 2;
  if (alive >= cap) return;
  const n = Math.min(cap - alive, M.heat === 2 ? 3 : 2);
