function hexFromIds(ids) { let mx = 0; ids.forEach((i) => { if (i > mx) mx = i; }); const b = new Uint8Array((mx >> 3) + 1); ids.forEach((i) => { b[i >> 3] |= 1 << (i & 7); }); return Array.from(b, (x) => ("0" + x.toString(16)).slice(-2)).join(""); }
function hexHas(h, i) { if (!h) return false; const p = (i >> 3) * 2; if (p + 2 > h.length) return false; return ((parseInt(h.substr(p, 2), 16) >> (i & 7)) & 1) === 1; }
function hexOr(a, b) { a = hexClean(a); b = hexClean(b); const n = Math.max(a.length, b.length); let o = ""; for (let p = 0; p < n; p += 2) { const x = (parseInt(a.substr(p, 2) || "0", 16) | parseInt(b.substr(p, 2) || "0", 16)) & 255; o += ("0" + x.toString(16)).slice(-2); } return o; }
function khasCover(doc) {
  const o = {};
  o.ts = 0; o.cs = 0;
  KLV.forEach((L) => { const ids = khasAll({ tk: L }).map((q) => q.i); o["t" + L] = ids.length; o["c" + L] = ids.filter((i) => hexHas(doc && doc[qf(L)], i)).length; o.ts += o["t" + L]; o.cs += o["c" + L]; });
  return o;
}
function khatamList(doc) { const c = khasCover(doc), a = []; KLV.forEach((L) => { if (c["t" + L] && c["c" + L] >= c["t" + L]) a.push("K" + L); }); if (KLV.length === 2 && a.length === 2) a.push("KS"); return a; }
function mergeTeamDoc(cur, nd) {
  const m = Object.assign({}, cur || {}, nd);
  m.k = Math.max((cur && cur.k) | 0, nd.k | 0);
  m.q4 = hexOr(cur && cur.q4, nd.q4); m.q5 = hexOr(cur && cur.q5, nd.q5);
  const kh = {}; String((cur && cur.kh) || "").split(",").concat(String(nd.kh || "").split(",")).forEach((x) => { if (KHAS_BY[x]) kh[x] = 1; });
  m.kh = Object.keys(kh).join(",");
  if (!m.q4) delete m.q4; if (!m.q5) delete m.q5; if (!m.kh) delete m.kh;
  return m;
}
function sqKhasRecord(ids) {
  const st = sqState();
  if (!st || !st.ada) return { none: 1 };
  if (!st.aktif) return { warn: 1, id: st.id, n: st.n };
  const a4 = [], a5 = [];
  ids.forEach((i) => { const q = QBYID[i]; if (!q) return; (qf(tkOf(q)) === "q4" ? a4 : a5).push(i); });
  const raw = Net.teams[st.id] || {};
  const before = khasCover(sqDoc(st.id));
  const nd = Object.assign({}, raw, { q4: hexOr(raw.q4, hexFromIds(a4)), q5: hexOr(raw.q5, hexFromIds(a5)) });
  const after = khasCover({ q4: nd.q4, q5: nd.q5 });
  const kn = khatamList({ q4: nd.q4, q5: nd.q5 }), old = String(raw.kh || "").split(",");
  const fresh = kn.filter((x) => old.indexOf(x) < 0);
  nd.kh = kn.join(",");
  Net.teams[st.id] = nd;
  (async () => {
    try {
      const sn = await Net.db.doc("pas/" + st.id).get(), cur = sn.exists ? sn.data() : null;
      const m = mergeTeamDoc(cur, nd);
      await Net.db.doc("pas/" + st.id).set(m);
      Net.teams[st.id] = m;
    } catch (e) { /* cuba lagi pada misi seterusnya */ }
  })();
  return { ok: 1, id: st.id, n: st.n, added: (after.cs - before.cs), cover: after, fresh: fresh };
}
function khasAfter(res, score) {
  const notes = [];
  if (res.khas === "KR") { notes.push({ t: "Operasi Rahsia tamat. Soalan " + (SUBJ === "tw" ? "peperiksaan akhir tahun" : "Operasi Rahsia") + " tidak dikira dalam Cabaran Kumpulan Soalan pasukan." }); return notes; }
  const r = sqKhasRecord(res.right || []);
  if (r.none) notes.push({ t: "Sertai pasukan (tab Pasukan) supaya soalan yang anda jawab betul dikira dalam Cabaran Kumpulan Soalan." });
  else if (r.warn) notes.push({ t: "Pasukan " + r.n + " belum mempunyai " + SQ_MIN + " ahli, jadi liputan soalan belum dikira.", warn: 1 });
  else {
    notes.push({ t: "Cabaran Kumpulan Soalan: pasukan " + r.n + " menambah " + r.added + " soalan baharu yang dijawab betul. " + KLV.map((L) => "Tingkatan " + L + ": " + r.cover["c" + L] + "/" + r.cover["t" + L]).join(". ") + "." });
    r.fresh.forEach((k) => { P.coin = (P.coin | 0) + 200; P.kcl = P.kcl || {}; P.kcl[r.id + ":" + k] = 1; notes.push({ t: "KHATAM! Pasukan anda telah menjawab betul semua soalan " + (k === "KS" ? "Tingkatan 4 dan 5" : "Tingkatan " + k.slice(1)) + ". +200 syiling." }); });
  }
  return notes;
}
/* skor terbaik Latihan Khas untuk papan pertandingan */
function khasRg(rg) { const kh = P.kh || {}; KHAS.forEach((k) => { const z = (kh[k.id] && kh[k.id].hs) | 0; if (z > 0) rg["z" + k.key] = z; }); }
function khasZStr() { const kh = P.kh || {}; return KHAS.map((k) => (kh[k.id] && kh[k.id].hs) | 0).join(","); }
function khasFromZ(s) { const a = String(s || "").split(",").map((x) => parseInt(x, 10) | 0); P.kh = P.kh || {}; KHAS.forEach((k, i) => { if (a[i] > 0 && !((P.kh[k.id] && P.kh[k.id].hs) > 0)) P.kh[k.id] = { b: 0, hs: a[i], n: 1, ok: 0, tot: 0 }; }); }
/* =====================================================================
   MISI KBAT  |  jawapan huraian disemak oleh AI (kunci API murid / pelayan cikgu)
   Kunci disimpan pada peranti sahaja (localStorage/sessionStorage), tidak pernah masuk profil P atau Firebase.
   ===================================================================== */
const KBAT = [{"s":"tw","t":"Islam sebagai al-Din","q":"Ali berkata, \"Islam hanya melibatkan solat, puasa dan zakat; urusan sekolah dan kerja tiada kaitan dengan agama.\" Huraikan pendapat anda tentang kenyataan Ali dengan merujuk konsep Islam sebagai al-Din.","isi":["Islam ialah cara hidup lengkap yang merangkumi akidah, ibadah dan akhlak","Islam, Iman dan Ihsan meliputi seluruh kehidupan, bukan ritual semata-mata","Bekerja, belajar dan menjalankan penyelidikan juga dikira ibadah apabila memenuhi syarat (ikhlas dan menepati sunnah)","Ihsan: beribadah seolah-olah melihat Allah SWT, dan yakin Allah sentiasa melihat kita"]},{"s":"tw","t":"Ibadah","q":"Seorang murid rajin bersolat di masjid tetapi suka meniru dalam peperiksaan. Terangkan mengapa tindakan ini bertentangan dengan konsep ibadah dan cadangkan penyelesaiannya.","isi":["Ibadah mesti ikhlas dan menepati sunnah (ittiba' as-sunnah)","Ibadah merangkumi ibadah khusus dan ibadah umum; belajar juga ibadah jika memenuhi syarat","Meniru ialah khianat dan bertentangan dengan akhlak, sehingga ibadah tidak sempurna","Penyelesaian: bertaubat, belajar bersungguh-sungguh, niat belajar kerana Allah SWT"]},{"s":"tw","t":"Pandangan Hidup Islam","q":"Seorang pengkritik berkata hukum Islam kolot dan tidak sesuai dengan dunia moden. Berdasarkan prinsip pandangan hidup Islam, bahaskan kenyataan tersebut.","isi":["Rabbaniyyah: hukum bersumberkan wahyu Allah SWT dan sesuai sepanjang zaman","Waqi'iyyah: Islam praktikal dan mampu diamalkan","Thabat dan Murunah: asas hukum tetap, tetapi cara pelaksanaan luwes mengikut keadaan","Syumuliyyah dan 'Alamiyyah: lengkap dan sesuai untuk semua manusia"]},{"s":"tw","t":"Wahyu dan Akal","q":"Seorang remaja berkata akal manusia sudah cukup untuk menentukan baik dan buruk, wahyu tidak diperlukan. Bincangkan peranan wahyu dan akal berserta kelemahan hujah remaja itu.","isi":["Wahyu mutlak dan terpelihara; akal sentiasa berubah dan terhad","Akal tidak mampu memikirkan perkara ghaib","Wahyu memandu akal dalam akidah, ibadah dan akhlak; akal membezakan hak dengan batil","Akal perlu dijaga daripada perkara yang merosakkan seperti arak dan dadah"]},{"s":"tw","t":"Hiburan Menurut Islam","q":"Sebuah sekolah ingin mengadakan konsert amal. Cadangkan garis panduan supaya hiburan itu menepati syarak dan jelaskan kepentingannya.","isi":["Niat yang betul (untuk kebajikan)","Mendapat kelulusan pihak berkuasa","Menutup aurat dan tiada pergaulan bebas","Menghormati waktu solat dan tidak melalaikan ibadah wajib","Kepentingan: meningkatkan iman dan takwa, menjaga jiwa dan maruah, selari dengan akhlak Islam"]},{"s":"tw","t":"Sistem Kewangan Islam","q":"Seorang pekerja ingin menyimpan dan melabur wang tetapi bimbang terlibat dengan riba. Terangkan dua cara muamalat Islam yang boleh dipilih dan kebaikannya.","isi":["Muamalat Islam bebas riba, gharar dan perjudian serta berasaskan kerelaan","Contoh: perbankan Islam, takaful, Tabung Haji, al-Rahnu, pelaburan patuh syariah","Takaful berasaskan ta'awun (tolong-menolong) dan tabarru'","Tanpa muamalat Islam berlaku riba, jurang kaya-miskin dan krisis hutang"]},{"s":"tw","t":"Sistem Perundangan Islam","q":"Ada pihak mendakwa hukuman Islam kejam. Jelaskan tiga asas dan matlamat perundangan Islam untuk menjawab dakwaan ini.","isi":["Tiga asas: pencegahan, pembalasan dan pemulihan","Lima matlamat: memelihara agama, nyawa, akal, keturunan dan harta","Hukuman adil tanpa mengira pangkat dan mendidik jiwa","Perundangan Islam ciptaan Allah SWT, lengkap dan sesuai semua zaman"]},{"s":"tw","t":"Sistem Pemerintahan","q":"Huraikan bagaimana Piagam Madinah dan prinsip syura menunjukkan keadilan dalam pemerintahan Islam, serta kesan jika tanggungjawab pemerintah atau rakyat diabaikan.","isi":["Piagam Madinah (622 M) perlembagaan bertulis pertama, 47 fasal, menjamin hak asasi dan kebebasan agama semua kaum","Prinsip negara Islam: syura, keadilan, kebebasan dan persamaan","Khalifah ialah pemegang amanah; rakyat taat selagi tidak bercanggah dengan syarak","Pengabaian tanggungjawab mengancam keselamatan negara dan mengundang kemurkaan Allah SWT"]},{"s":"pi","t":"Larangan Rasuah","q":"Seorang pegawai menerima hadiah daripada kontraktor supaya projeknya diluluskan. Jelaskan hukum perbuatan itu dan kesannya kepada individu dan masyarakat.","isi":["Rasuah ialah pemberian atau suapan untuk memalsukan kebenaran dan membenarkan kepalsuan (al-Baqarah ayat 188)","Menerima dan memberi rasuah dan menyalahgunakan jawatan ialah kesalahan","Kesan: dilaknat Allah dan Rasul, maruah tercemar","Masyarakat menjadi tidak adil; carilah rezeki halal"]},{"s":"pi","t":"Mempersendakan Agama","q":"Seorang rakan menjadikan hadis sebagai bahan lawak di media sosial. Nasihatkan beliau dengan merujuk surah al-An'am ayat 70.","isi":["Ayat 70 memerintahkan menjauhi orang yang menjadikan agama sebagai permainan dan senda gurau","Bentuk mempersendakan agama termasuk mengejek sunnah dan menghina ulama","Boleh membawa kepada hilang iman","Cara menjaga kesucian agama: ilmu, mencontohi akhlak Rasulullah SAW, mempertingkat ibadat"]},{"s":"pi","t":"Kemuliaan Berdikari","q":"Zaid sering meminta wang saku daripada rakan walaupun mampu bekerja sambilan. Huraikan nasihat anda berdasarkan konsep berdikari dalam Islam.","isi":["Berdikari ialah berusaha sendiri dan tidak bergantung kepada orang lain","Tangan yang memberi lebih baik daripada tangan yang meminta","Teladan Nabi Daud AS makan daripada hasil usaha tangannya sendiri","Berdikari membina maruah diri dan menjauhkan sikap meminta-minta"]},{"s":"pi","t":"Hindari Ajaran Sesat","q":"Seorang murid diajak menyertai sebuah kumpulan yang mendakwa pemimpinnya boleh menebus dosa pengikut. Terangkan ciri ajaran sesat dan tindakan yang patut diambil.","isi":["Ajaran sesat bercanggah dengan al-Quran dan al-Sunnah walaupun mendakwa ajaran Islam","Ciri: mengaku nabi/rasul, mendakwa imam al-Mahdi, mendakwa guru boleh menebus dosa","Faktor: jahil akidah, pengaruh rakan sebaya dan media sosial","Tindakan: menolak ajakan, belajar akidah yang sahih, memaklumkan guru atau pihak berkuasa agama"]},{"s":"pi","t":"Wasatiyyah","q":"Seorang remaja terlalu menumpukan ibadat sunat sehingga mengabaikan pelajaran dan kesihatan. Berdasarkan konsep wasatiyyah, jelaskan kesilapannya dan cara memperbaikinya.","isi":["Wasatiyyah ialah sederhana, seimbang, adil dan cemerlang","Keseimbangan: ibadat fardu dan sunat, kesihatan jasmani, penggunaan akal, keperluan fitrah","Tidak bersikap melampau (ghuluw) dan tidak mengabaikan (tafrit)","Hikmah: masyarakat aman, pendidikan meningkat, syiar Islam tegak"]},{"s":"pi","t":"Kepelbagaian Bangsa","q":"Dalam kelas anda ada rakan pelbagai kaum yang kadangkala diejek. Terangkan pengajaran surah al-Hujurat ayat 13 dan cadangkan tindakan anda.","isi":["Allah menjadikan manusia berbangsa-bangsa supaya saling mengenali","Yang paling mulia di sisi Allah ialah yang paling bertakwa","Tiada kelebihan sesuatu bangsa atas yang lain kecuali dengan takwa","Perpaduan dan toleransi menjadi asas hidup bermasyarakat; hentikan ejekan"]},{"s":"pi","t":"Adab Menjaga Alam Sekitar","q":"Sebuah sungai berhampiran sekolah tercemar akibat sampah. Huraikan tanggungjawab murid sebagai khalifah dan langkah yang boleh diambil.","isi":["Manusia ialah khalifah yang bertanggungjawab menjaga bumi daripada kerosakan","Larangan membazir air dan mencemarkan sumber air","Punca: kurang kesedaran sivik dan tidak takut undang-undang","Hikmah: persekitaran bersih, ketenangan jiwa, eko-pelancongan menambah pendapatan"]},{"s":"pi","t":"Sifat Mazmumah","q":"Farid berasa tidak senang apabila rakannya mendapat keputusan cemerlang dan berharap rakan itu gagal. Kenal pasti sifat tersebut dan cadangkan cara mengatasinya.","isi":["Sifat hasad: dengki melihat kelebihan orang lain dan mengharap kelebihan itu hilang","Berbeza daripada ghibtah yang dibenarkan: ingin memiliki nikmat serupa tanpa mengharap ia hilang","Cara: muhasabah diri, mengawal nafsu, berzikir","Bersahabat dengan orang baik"]},{"s":"p3","t":"Kejadian Manusia","q":"Meneliti dan memikirkan tentang kejadian manusia membawa keinsafan. Berdasarkan pernyataan ini, huraikan pendapat anda.","isi":["Menyakini Allah SWT mencipta kejadian manusia yang sangat unik","Menyakini kejadian manusia bukti kekuasaan Allah SWT","Menyakini setiap ciptaan Allah SWT sangat sempurna","Jawapan lain yang munasabah diterima"]},{"s":"p3","t":"Hindari Sifat Negatif","q":"Hadis Anas bin Malik memohon perlindungan daripada lemah, malas, pengecut dan nyanyuk. Terangkan dua pengajaran yang dapat diambil daripada hadis tersebut.","isi":["Sentiasa berdoa agar dijauhkan daripada sifat-sifat yang tidak disukai Rasulullah SAW","Berusaha menjadi orang yang kuat kerana mukmin yang kuat lebih dicintai Allah SWT","Rajin meningkatkan kebaikan untuk berubah daripada kemunduran kepada kemajuan","Berani dalam segala perkara kebaikan"]},{"s":"p3","t":"Beriman kepada Hari Akhirat","q":"Terangkan dua kesan beriman kepada hari akhirat dalam kehidupan seseorang.","isi":["Meninggalkan maksiat kerana yakin segala amalan akan dibentangkan dan dihisab","Memperbanyak amalan soleh kerana yakin Allah SWT akan menghitung amalan manusia","Jawapan lain yang munasabah diterima"]},{"s":"p3","t":"Beriman kepada Qada dan Qadar","q":"Zarul sering mengeluh apabila ditimpa penyakit. Sebagai seorang rakan, apakah nasihat anda kepada Zarul?","isi":["Bersabar dengan apa yang berlaku","Menerima takdir Allah SWT dengan hati terbuka","Reda dengan ketentuan Allah SWT","Jawapan lain yang munasabah diterima"]},{"s":"p3","t":"Hari Raya Aidilfitri dan Aidiladha","q":"Pada pendapat anda, sejauh manakah sambutan hari raya dapat menyemarakkan ukhuwah dalam kalangan umat Islam di Malaysia? Berikan ulasan anda.","isi":["Amalan ziarah-menziarahi dapat menyemarakkan ukhuwah","Menunaikan solat sunat hari raya dan mendengar khutbah raya di masjid secara berjemaah","Amalan bertukar juadah di hari raya","Jawapan lain yang munasabah diterima"]},{"s":"p3","t":"Qiyamullail","q":"Terangkan kelebihan seseorang yang mengamalkan qiamullail dalam kehidupan dan nyatakan dua amalan Rasulullah SAW sebelum qiamullail.","isi":["Kelebihan: doa dimakbulkan Allah SWT","Menjadi hamba yang bersyukur dan mendapat kemuliaan di sisi Allah SWT","Memberi ketenangan kepada jiwa dan beroleh balasan syurga","Amalan sebelum qiamullail: bersiwak dan memandang ke langit"]},{"s":"p3","t":"Adab Bermusafir","q":"Terangkan hikmah mengamalkan adab bermusafir dalam Islam.","isi":["Perjalanan diberkati Allah SWT kerana merapatkan hubungan hamba dengan pencipta","Memberi ketenangan hati kerana pergantungan harapan kepada Allah SWT","Perjalanan menjadi mudah dan lancar apabila melantik seorang ketua jika melebihi tiga orang","Mendidik jiwa lebih berdisiplin kerana mematuhi undang-undang semasa bermusafir"]},{"s":"p3","t":"Adab Berkomunikasi","q":"Kerajaan telah melancarkan pelbagai kempen untuk mewujudkan kesedaran penggunaan internet secara berhemah. Ramalkan apa yang akan berlaku sekiranya kempen tersebut diabaikan.","isi":["Berlakunya peningkatan jenayah siber seperti buli siber","Maklumat peribadi terdedah dan mudah digodam","Peningkatan jenayah sosial dan maksiat","Jawapan lain yang munasabah diterima"]},{"s":"p3","t":"Pemaaf","q":"Rasulullah SAW memaafkan musyrikin Makkah selepas pembukaan Kota Makkah. Huraikan pengajaran daripada peristiwa itu kepada seorang murid yang pernah dibuli oleh rakannya.","isi":["Rasulullah SAW mengisytiharkan kemaafan kepada musyrikin Makkah","Memaafkan memberi ketenangan jiwa dan mendapat keredaan Allah SWT","Menahan marah dan memaafkan kesalahan orang ialah sifat orang bertakwa (Ali Imran ayat 134)","Memaafkan membawa masyarakat hidup harmoni, tetapi tindakan melindungi diri atau melapor kepada guru tetap wajar"]},{"s":"p3","t":"Hindari Sifat Negatif dan Akhlak","q":"Seorang murid menyebarkan mesej yang belum disahkan kebenarannya sehingga rakannya malu. Terangkan kesalahan murid itu dan adab berkomunikasi yang sepatutnya diamalkan.","isi":["Tidak menyebarkan fitnah dan membuka aib orang lain","Memastikan kesahihan maklumat sebelum menyebarkan","Menggunakan bahasa yang sesuai dan sopan","Tidak melalaikan daripada melakukan ibadah dan tanggungjawab"]},{"s":"ba","t":"التركيب الإضافي والنعتي","q":"Tulis tiga ayat pendek dalam bahasa Arab tentang sekolah anda. Gunakan sekurang-kurangnya satu tarkib idhafi (contoh: كتابُ الطالبِ) dan satu tarkib na'ti (contoh: الطالبُ المجتهدُ). Tandakan tarkib yang anda guna.","isi":["Ayat relevan dengan tema sekolah","Ada tarkib idhafi yang betul: mudhaf tanpa ال dan tanwin, mudhaf ilaih majrur","Ada tarkib na'ti yang betul: na't mengikut man'ut dari segi i'rab, ta'rif/tankir, jantina dan bilangan","Ejaan dan baris akhir munasabah"]},{"s":"ba","t":"كان وأخواتها وإنّ وأخواتها","q":"Tulis dua ayat menggunakan كان dan dua ayat menggunakan إنّ. Terangkan dalam Bahasa Melayu perubahan baris pada mubtada' dan khabar dalam setiap ayat.","isi":["Kana merafa'kan mubtada' (ism kana) dan menasabkan khabar (khabar kana)","Inna menasabkan mubtada' (ism inna) dan merafa'kan khabar (khabar inna)","Contoh ayat Arab betul untuk kedua-dua struktur, misalnya كانَ الجوُّ جميلاً / إنَّ الطالبَ مجتهدٌ","Penerangan perubahan baris tepat"]},{"s":"ba","t":"لم والمضارع المجزوم","q":"Tulis tiga ayat Arab yang menafikan perbuatan lampau menggunakan لم + fi'il mudhari'. Jelaskan tanda jazam pada setiap fi'il.","isi":["Menggunakan لم dengan fi'il mudhari' majzum yang betul","Jazam: sukun pada huruf akhir fi'il biasa","Fi'il af'al khamsah: buang nun","Ayat bermakna dan menafikan peristiwa lampau"]},{"s":"ba","t":"المجال التقني","q":"Tulis tiga ayat Arab tentang kegunaan telefon pintar atau internet dalam pembelajaran. Gunakan sekurang-kurangnya tiga perkataan daripada tema teknologi (الإنترنت، الحاسوب، الهاتف الذكي، التطبيق).","isi":["Ayat relevan dengan pembelajaran dan teknologi","Menggunakan sekurang-kurangnya tiga kosa kata tema teknologi","Struktur ayat dan i'rab asas munasabah","Ayat boleh difahami dan lengkap"]},{"s":"ba","t":"الفاعل والمفعول به","q":"Terangkan dalam Bahasa Melayu perbezaan fa'il dan maf'ul bih serta beri dua contoh ayat Arab lengkap dengan baris akhir.","isi":["Fa'il ialah pelaku perbuatan dan sentiasa marfu'","Maf'ul bih ialah yang dikenakan perbuatan dan sentiasa mansub","Contoh ayat Arab betul, misalnya كتبَ الطالبُ الدرسَ","Menandakan fa'il dan maf'ul bih dengan tepat"]},{"s":"ba","t":"المجال الاجتماعي: الكوارث والإغاثة","q":"Tulis tiga ayat Arab tentang bantuan kepada mangsa banjir. Gunakan kosa kata tema bencana dan bantuan.","isi":["Ayat relevan dengan tema bencana dan pertolongan","Menggunakan kosa kata seperti الكوارث، الفيضان، الإغاثة","Struktur ayat dan baris akhir munasabah","Ayat lengkap dan boleh difahami"]},{"s":"sj","t":"Warisan Negara Bangsa","q":"Kesultanan Melayu Melaka sering dianggap sebagai asas negara bangsa Malaysia. Huraikan pendapat anda tentang kenyataan ini dengan merujuk warisan pentadbiran dan undang-undang Melaka.","isi":["Melaka mempunyai ciri negara bangsa: raja, rakyat, wilayah, undang-undang dan kedaulatan","Sistem pemerintahan beraja dan pembesar berempat serta Hukum Kanun Melaka diwarisi dalam sistem pentadbiran negara","Islam, bahasa Melayu dan adat menjadi asas jati diri yang diteruskan dalam Perlembagaan","Melaka diiktiraf melalui hubungan diplomatik dan perdagangan antarabangsa, mencerminkan kedaulatan"]},{"s":"sj","t":"Kebangkitan Nasionalisme","q":"Nasionalisme di Asia bangkit dengan pelbagai bentuk. Bincangkan sebab semangat nasionalisme di Tanah Melayu muncul selepas Perang Dunia Kedua.","isi":["Kesedaran politik yang dipupuk oleh pendidikan, akhbar dan gerakan Islah","Pendudukan Jepun menyedarkan orang Melayu bahawa penjajah barat boleh dikalahkan","Penentangan terhadap Malayan Union menyatukan orang Melayu dan melahirkan UMNO","Pengaruh nasionalisme di Indonesia, India dan negara Asia lain"]},{"s":"sj","t":"Konflik Dunia dan Pendudukan Jepun","q":"Pendudukan Jepun di Tanah Melayu membawa kesan buruk dan kesan positif. Jelaskan kesan jangka panjang pendudukan ini terhadap kebangkitan nasionalisme.","isi":["Kesan buruk: kekejaman, kekurangan makanan, ketegangan kaum, wang pisang","Semangat anti-penjajah meningkat kerana kekalahan British menghapuskan mitos kuasa barat tidak terkalahkan","Orang Melayu mendapat latihan ketenteraan (Giyugun, Giyutai) dan kesedaran politik","Ketegangan antara kaum akibat sokongan MPAJA dan kerjasama dengan Jepun menjejaskan hubungan kaum selepas perang"]},{"s":"sj","t":"Era Peralihan Kuasa British","q":"Mengapakah penentangan orang Melayu terhadap Malayan Union berjaya? Hujahkan dengan bukti.","isi":["Raja-raja Melayu dilucutkan kedaulatan dan kuasa dalam Malayan Union melalui perjanjian yang dipaksa oleh Harold MacMichael","Kedudukan istimewa orang Melayu terjejas dan syarat kerakyatan terlalu longgar","Penyatuan orang Melayu di bawah UMNO diketuai Dato' Onn Jaafar, termasuk Kongres Melayu, demonstrasi dan boikot","Bantahan Raja-raja Melayu serta sokongan bekas pegawai British menyebabkan British membatalkannya"]},{"s":"sj","t":"Persekutuan Tanah Melayu 1948","q":"Persekutuan Tanah Melayu 1948 dianggap lebih baik daripada Malayan Union. Rasionalkan kenyataan tersebut.","isi":["Kedaulatan Raja-raja Melayu dan negeri dikekalkan dengan Majlis Mesyuarat Perundangan dan Majlis Mesyuarat Negeri","Kedudukan istimewa orang Melayu terjamin","Syarat kerakyatan lebih ketat dan sesuai dengan keadaan negara","Dirunding bersama wakil Raja-raja Melayu, UMNO dan British, bukan dipaksa"]},{"s":"sj","t":"Ancaman Komunis dan Perisytiharan Darurat","q":"Bincangkan strategi kerajaan British dan kerajaan Persekutuan menghapuskan ancaman komunis semasa Darurat. Nilaikan keberkesanannya.","isi":["Rancangan Briggs: Petempatan Baru memutuskan bekalan komunis dengan orang awam","Rancangan Templer: Hati dan Fikiran serta kawasan putih","Operasi tentera dan pasukan khas memburu komunis di dalam hutan","Perisytiharan Merdeka dan tawaran pengampunan Baling menarik pengunduran komunis"]},{"s":"sj","t":"Usaha ke Arah Kemerdekaan","q":"Pembentukan Parti Perikatan menjadi asas kemerdekaan. Jelaskan kepentingan permuafakatan kaum dalam mencapai kemerdekaan.","isi":["Kerjasama UMNO, MCA dan MIC memperlihatkan perpaduan kaum","Kemenangan Perikatan dalam pilihan raya membuktikan sokongan rakyat berbilang kaum","Muafakat kaum menyelesaikan isu kerakyatan, bahasa dan kedudukan istimewa dalam Suruhanjaya Reid","Pihak British yakin Tanah Melayu bersedia merdeka kerana rakyatnya bersatu"]},{"s":"sj","t":"Pilihan Raya","q":"Pilihan raya umum 1955 ialah detik penting bagi Tanah Melayu. Huraikan pentingnya pilihan raya tersebut.","isi":["Pilihan raya umum pertama untuk Majlis Perundangan Persekutuan, rakyat memilih wakil sendiri","Perikatan memenangi 51 daripada 52 kerusi, mendapat mandat untuk menuntut kemerdekaan","Tunku Abdul Rahman menjadi Ketua Menteri dan kemudian mengetuai rombongan ke London pada 1956","Menunjukkan rakyat bersedia menjalankan demokrasi"]},{"s":"sj","t":"Perlembagaan Persekutuan Tanah Melayu 1957","q":"Perlembagaan Persekutuan 1957 menjadi sumber kuasa tertinggi negara. Jelaskan peruntukan penting yang menjamin keharmonian rakyat berbilang kaum.","isi":["Islam sebagai agama Persekutuan (Perkara 3) dengan kebebasan beragama lain","Bahasa Melayu sebagai bahasa kebangsaan (Perkara 152)","Kedudukan istimewa orang Melayu dan kepentingan sah kaum lain (Perkara 153)","Kerakyatan yang adil dan Raja berperlembagaan sebagai payung negara"]},{"s":"sj","t":"Pemasyhuran Kemerdekaan","q":"Pada pendapat anda, mengapakah kemerdekaan perlu dipertahankan oleh generasi muda? Berikan hujah dengan merujuk peristiwa 31 Ogos 1957.","isi":["Kemerdekaan diperoleh melalui rundingan dan pengorbanan para pemimpin dan rakyat","Pemasyhuran di Stadium Merdeka dengan tujuh laungan 'Merdeka' menandakan kedaulatan negara","Kedaulatan negara mesti dipertahankan daripada ancaman luar dan perpecahan dalaman","Generasi muda perlu mengisi kemerdekaan dengan perpaduan, ilmu dan patriotisme"]},{"s":"sj","t":"Pembentukan Malaysia","q":"Pembentukan Malaysia pada 1963 membawa manfaat tetapi menghadapi cabaran. Huraikan sebab Sabah dan Sarawak bersetuju menyertai Malaysia.","isi":["Kemajuan ekonomi dan pembangunan melalui gabungan dengan Persekutuan Tanah Melayu","Jaminan keselamatan daripada ancaman komunis dan kuasa luar","18/20 Perkara serta Perjanjian Malaysia 1963 menjamin hak Sabah dan Sarawak","Laporan Suruhanjaya Cobbold dan Jawatankuasa Antara Kerajaan menunjukkan majoriti menyokong"]},{"s":"sj","t":"Dasar Ekonomi Baru dan Dasar Pembangunan Nasional","q":"Jelaskan kejayaan Dasar Ekonomi Baru (DEB) dalam membasmi kemiskinan dan menyusun semula masyarakat. Pada pandangan anda, adakah DEB masih relevan?","isi":["Kadar kemiskinan menurun daripada 49.3% (1970) kepada 17.1% (1990)","Peningkatan pemilikan modal bumiputera dan kemunculan golongan pertengahan","Melalui FELDA, RISDA, MARA, PNB dan Rancangan Buku Hijau","Aspek pengagihan yang adil dan perpaduan kaum perlu diteruskan; DPN dan dasar baharu meneruskan matlamat ini"]},{"s": "sc", "t": "Langkah Keselamatan di Makmal", "q": "Seorang murid memanaskan bahan kimia dalam tabung uji sambil memakai kasut terbuka dan tidak memakai cermin mata keselamatan. Huraikan risiko dan langkah keselamatan yang sepatutnya diambil.", "isi": ["Memakai peralatan pelindung diri: kot makmal, cermin mata keselamatan, sarung tangan dan kasut tertutup", "Memanaskan tabung uji dengan mulutnya dihalakan jauh daripada diri dan orang lain", "Mengetahui lokasi pancuran air kecemasan, pemadam api dan kotak pertolongan cemas", "Melaporkan kemalangan atau tumpahan kepada guru serta-merta"]},{"s": "sc", "t": "Bantuan Kecemasan", "q": "Anda melihat seseorang rebah dan tidak bernafas di tempat awam. Bincangkan langkah bantuan kecemasan yang perlu anda lakukan secara berurutan.", "isi": ["Pastikan keadaan sekeliling selamat dan periksa respons mangsa", "Minta orang lain menghubungi talian kecemasan 999 sambil mula memberi bantuan", "Buka saluran pernafasan dan periksa pernafasan; lakukan CPR jika tidak bernafas", "Teruskan sehingga bantuan paramedik tiba dan jangan menghentikan CPR tanpa sebab"]},{"s": "sc", "t": "Parameter Kesihatan Badan", "q": "Pada pendapat anda, mengapakah pemeriksaan suhu badan, kadar nadi, tekanan darah dan BMI penting dilakukan secara berkala? Wajarkan jawapan anda.", "isi": ["Parameter ini menunjukkan status kesihatan dan membolehkan penyakit dikesan lebih awal", "Tekanan darah tinggi boleh meningkatkan risiko strok dan penyakit jantung", "BMI membantu menilai sama ada berat badan sihat, kurang atau berlebihan", "Pemantauan berkala membantu mengubah gaya hidup sebelum penyakit serius berlaku"]},{"s": "sc", "t": "Teknologi Hijau dalam Melestarikan Alam Sekitar", "q": "Sebuah sekolah ingin menjadi sekolah hijau. Cadangkan langkah yang menggunakan konsep Teknologi Hijau dan jelaskan manfaatnya.", "isi": ["Menjimatkan tenaga: lampu LED, penyaman udara 24–25°C, label kecekapan tenaga", "Pengasingan sisa mengikut konsep 5R dan membuat kompos daripada sisa kantin", "Menggunakan pengangkutan awam atau berkongsi kenderaan untuk mengurangkan jejak karbon", "Manfaat: mengurangkan pencemaran, menjimatkan kos dan memupuk kesedaran murid"]},{"s": "sc", "t": "Genetik", "q": "Pasangan suami isteri yang sama-sama pembawa gen resesif suatu penyakit ingin merancang keluarga. Terangkan kebarangkalian anak mereka menghidap penyakit dan cara penyakit boleh dikesan lebih awal.", "isi": ["Ibu bapa pembawa (Aa × Aa) menghasilkan anak dengan nisbah genotip 1AA : 2Aa : 1aa", "Kebarangkalian anak menghidap penyakit (aa) ialah 25 peratus", "Pengesanan awal melalui amniosentesis dan kariotip untuk mengesan keabnormalan kromosom", "Nasihat genetik dan saringan sebelum perkahwinan membantu membuat keputusan yang bijak"]},{"s": "sc", "t": "Sokongan, Pergerakan dan Pertumbuhan", "q": "Mengapakah jerung dan paus yang terdampar di darat sukar bernafas dan bergerak, sedangkan di laut mereka bergerak dengan mudah? Huraikan dengan merujuk sistem sokongan.", "isi": ["Haiwan akuatik disokong terutamanya oleh daya apungan air", "Di darat, tiada daya apungan dan berat badan perlu ditanggung oleh rangka", "Lengkungan pektoral dan pelvis haiwan akuatik kecil, tidak sesuai menyokong berat badan", "Badan besar yang tertekan oleh graviti menjejaskan pernafasan dan pergerakan"]},{"s": "sc", "t": "Koordinasi Badan", "q": "Seorang remaja mula menyalahgunakan dadah dan sering minum minuman beralkohol. Bincangkan kesan penyalahgunaan itu terhadap koordinasi badan dan kesihatan mental, serta cadangkan langkah mengatasinya.", "isi": ["Dadah dan alkohol mengganggu fungsi neuron dan melambatkan atau mengubah impuls", "Koordinasi otot lemah, pertuturan tidak jelas dan hilang keseimbangan", "Kerosakan hati (sirosis), ulser perut serta masalah mental seperti halusinasi dan paranoid", "Langkah: nasihat dan rawatan pemulihan, sokongan keluarga dan menjauhi pengaruh rakan sebaya"]},{"s": "sc", "t": "Unsur dan Bahan", "q": "Mengapakah atom natrium cenderung membentuk ion positif manakala atom klorin membentuk ion negatif? Jelaskan dengan merujuk susunan elektron.", "isi": ["Natrium (2.8.1) menderma satu elektron untuk mencapai susunan oktet yang stabil", "Klorin (2.8.7) menerima satu elektron untuk mencapai susunan oktet 2.8.8", "Atom logam menderma elektron membentuk ion positif; atom bukan logam menerima elektron membentuk ion negatif", "Ion yang bertentangan cas saling tertarik membentuk sebatian ion seperti garam biasa"]},{"s": "sc", "t": "Kimia Industri", "q": "Sebuah syarikat ingin membuat badan pesawat dan tayar kenderaan. Cadangkan bahan yang sesuai bagi setiap produk dan wajarkan pilihan anda.", "isi": ["Badan pesawat: aloi duralumin yang ringan, kuat dan tahan kakisan", "Aloi lebih keras daripada logam tulen kerana atom asing menyukarkan penggelongsoran lapisan atom", "Tayar: getah tervulkan kerana sulfur membentuk rangkai silang menjadikannya lebih keras dan tahan haba", "Getah asli tidak sesuai kerana lembut dan lembik apabila panas"]},{"s": "sc", "t": "Kimia dalam Perubatan dan Kesihatan", "q": "Seorang pesakit enggan menghabiskan antibiotik kerana berasa sihat selepas dua hari. Bincangkan kesan tindakan ini dan nasihat yang sesuai.", "isi": ["Antibiotik perlu dihabiskan mengikut dos untuk memastikan bakteria dihapuskan", "Bakteria yang tinggal boleh menjadi rintang dan penyakit kembali", "Penyalahgunaan ubat boleh menyebabkan kesan sampingan dan ubat kurang berkesan", "Sentiasa ikut preskripsi doktor atau farmasi"]},{"s": "sc", "t": "Daya dan Gerakan", "q": "Mengapakah pemandu dan penumpang perlu memakai tali pinggang keledar, walaupun kereta bergerak perlahan? Terangkan dengan konsep inersia.", "isi": ["Inersia ialah sifat objek menentang perubahan keadaan asal (gerakan)", "Apabila kereta berhenti tiba-tiba, badan penumpang terus bergerak ke hadapan", "Tali pinggang keledar dan beg udara menghalang penumpang terhumban ke hadapan", "Semakin besar jisim, semakin besar inersia, maka kesan lebih teruk pada kenderaan berat"]},{"s": "sc", "t": "Tenaga Nuklear", "q": "Adakah wajar Malaysia membina stesen jana kuasa nuklear? Bahaskan dengan mengemukakan hujah menyokong dan menentang.", "isi": ["Menyokong: bahan api fosil akan habis, tenaga nuklear besar dan membebaskan gas rumah hijau yang sedikit", "Menyokong: memenuhi permintaan elektrik yang semakin meningkat", "Menentang: sisa radioaktif berbahaya jika tidak dikendalikan dengan cermat", "Menentang: risiko kemalangan dan kos pembinaan yang tinggi serta keperluan kepakaran"]},{"s": "sc", "t": "Mikroorganisma", "q": "Pengambilan antibiotik yang tidak mengikut dos boleh menyebabkan rintangan antibiotik. Bincangkan cara mikroorganisma boleh dimanfaatkan dan dikawal dalam kehidupan.", "isi": ["Bakteria dan kulat bermanfaat dalam penghasilan makanan, ubat dan pengurusan sisa", "Mikroorganisma patogen boleh dikawal dengan kebersihan, vaksin dan sterilisasi", "Antibiotik perlu digunakan mengikut preskripsi bagi mengelakkan rintangan", "Pengetahuan mikrobiologi membantu mencegah penyakit berjangkit"]},{"s": "sc", "t": "Nutrisi dan Teknologi Makanan", "q": "Mengapakah makanan diawet dan diproses? Wajarkan penggunaan teknologi makanan serta kebimbangan pengguna terhadap bahan tambah makanan.", "isi": ["Pengawetan melambatkan pertumbuhan mikroorganisma dan memanjangkan jangka hayat", "Teknologi makanan meningkatkan nutrisi dan keselamatan makanan", "Bahan tambah mesti mengikut peraturan kesihatan dan dibaca pada label", "Pengguna perlu memilih makanan seimbang dan mengelakkan pengambilan berlebihan"]},{"s": "sc", "t": "Kelestarian Alam Sekitar", "q": "Pembangunan pesat boleh menjejaskan alam sekitar. Cadangkan cara mengimbangi pembangunan dengan kelestarian alam sekitar.", "isi": ["Menggunakan tenaga boleh baharu dan teknologi hijau", "Mengawal pencemaran dengan undang-undang dan penguatkuasaan", "Melindungi hutan dan kepelbagaian biodiversiti", "Pendidikan dan penyertaan masyarakat dalam amalan lestari"]},{"s": "sc", "t": "Kadar Tindak Balas", "q": "Sebuah kilang mahu mempercepat penghasilan suatu produk. Cadangkan cara meningkatkan kadar tindak balas dan terangkan menggunakan teori perlanggaran.", "isi": ["Menaikkan suhu: zarah bergerak lebih laju, perlanggaran lebih kerap dan lebih bertenaga", "Menambah kepekatan: lebih banyak zarah dalam isi padu tertentu, perlanggaran lebih kerap", "Mengecilkan saiz bahan: luas permukaan bertambah", "Menggunakan mangkin yang menurunkan tenaga pengaktifan"]},{"s": "sc", "t": "Sebatian Karbon", "q": "Pembakaran bahan api fosil menyebabkan pencemaran dan pemanasan global. Bincangkan peranan sebatian karbon sebagai bahan api dan alternatif yang lebih mesra alam.", "isi": ["Hidrokarbon terbakar membebaskan tenaga tetapi menghasilkan karbon dioksida", "Karbon dioksida menyumbang kepada kesan rumah hijau dan pemanasan global", "Pembakaran tidak lengkap menghasilkan karbon monoksida yang beracun", "Alternatif: biofuel dan tenaga boleh baharu"]},{"s": "sc", "t": "Elektrokimia", "q": "Mengapakah sudu besi disadur dengan kuprum atau perak? Terangkan proses penyaduran dan manfaatnya.", "isi": ["Penyaduran menggunakan elektrolisis; objek dijadikan katod", "Anod ialah logam penyadur dan elektrolit mengandungi ion logam yang sama", "Melindungi daripada kakisan dan menambah keindahan", "Contoh: penyaduran sudu, perhiasan dan komponen kenderaan"]},{"s": "sc", "t": "Cahaya dan Optik", "q": "Mengapakah ikan kelihatan lebih dekat dengan permukaan air daripada kedudukan sebenar? Jelaskan dengan konsep pembiasan cahaya.", "isi": ["Cahaya dibiaskan apabila bergerak daripada air ke udara kerana halaju berbeza", "Cahaya menjauhi normal apabila memasuki medium kurang tumpat", "Mata menganggap cahaya bergerak lurus, maka imej kelihatan lebih cetek", "Tombak pemburu perlu disasarkan lebih rendah daripada kedudukan imej"]},{"s": "sc", "t": "Daya dan Tekanan", "q": "Mengapakah dam dibina lebih tebal di bahagian bawah? Terangkan dengan konsep tekanan cecair.", "isi": ["Tekanan cecair bertambah dengan kedalaman", "Tekanan cecair = ketumpatan × pecutan graviti × kedalaman", "Bahagian bawah dam perlu menahan tekanan yang lebih besar", "Dinding yang lebih tebal mencegah dam retak atau runtuh"]},{"s": "sc", "t": "Teknologi Angkasa Lepas", "q": "Mengapakah angkasawan perlu memakai pakaian angkasa dan mengapa penerokaan angkasa lepas bermanfaat kepada kehidupan di Bumi?", "isi": ["Angkasa lepas ialah vakum: tiada tekanan udara, oksigen dan suhu ekstrem", "Pakaian angkasa membekalkan oksigen, mengekalkan tekanan dan suhu serta melindungi daripada sinaran", "Teknologi angkasa digunakan dalam komunikasi satelit, ramalan cuaca dan navigasi GPS", "Penerokaan angkasa menghasilkan inovasi dalam perubatan dan bahan"]},{"s": "mt", "t": "Fungsi dan Persamaan Kuadratik", "q": "Sebuah bola dibaling ke atas dan ketinggiannya diwakili oleh h = −5t² + 20t. Bagaimanakah anda menentukan ketinggian maksimum dan masa bola jatuh ke tanah? Jelaskan makna jawapan anda.", "isi": ["Ketinggian maksimum pada paksi simetri t = −b/2a = 2 saat, iaitu h = 20 meter", "Bola jatuh ke tanah apabila h = 0: −5t(t − 4) = 0, maka t = 4 saat", "Dua punca t = 0 (dilambung) dan t = 4 (mendarat) mewakili titik permulaan dan penghujung", "Parabola terbuka ke bawah (a < 0) menunjukkan titik maksimum"]},{"s": "mt", "t": "Asas Nombor", "q": "Mengapakah komputer menggunakan sistem nombor asas 2 dan bukan asas 10? Terangkan bagaimana nombor 13 diwakili dan bagaimana ia berkaitan dengan keadaan hidup dan mati litar elektronik.", "isi": ["Litar elektronik mempunyai dua keadaan: hidup (1) dan mati (0)", "13 = 1101₂ kerana 8 + 4 + 0 + 1", "Dua keadaan lebih mudah, tahan hingar dan murah berbanding sepuluh aras voltan", "Satu digit perduaan ialah satu bit; lapan bit membentuk satu bait"]},{"s": "mt", "t": "Penaakulan Logik", "q": "Seorang ahli politik berkata: 'Jika kita membina lebih banyak jalan raya, maka ekonomi akan maju. Ekonomi telah maju, maka jalan raya telah dibina.' Nilaikan sama ada penaakulan itu sah.", "isi": ["Premis berbentuk 'Jika p maka q' dan q benar", "Menyimpulkan p daripada q ialah kesilapan mengesahkan akibat", "Ekonomi boleh maju kerana sebab lain seperti pelaburan atau eksport", "Hujah yang sah memerlukan bentuk 'Jika p maka q; p benar; maka q benar' atau kontrapositif"]},{"s": "mt", "t": "Operasi Set", "q": "Dalam satu kelas 40 murid, 22 murid menyertai Kelab Bola Sepak, 18 menyertai Kelab Robotik dan 8 menyertai kedua-duanya. Bagaimanakah anda boleh menggunakan gambar rajah Venn untuk menentukan murid yang tidak menyertai mana-mana kelab dan apa kesimpulan guru boleh buat?", "isi": ["n(A ∪ B) = 22 + 18 − 8 = 32", "Murid tanpa kelab = 40 − 32 = 8", "Bola sepak sahaja = 14 dan robotik sahaja = 10", "Guru boleh menggalakkan 8 murid itu menyertai kelab bagi pembangunan kokurikulum"]},{"s": "mt", "t": "Rangkaian dalam Teori Graf", "q": "Sebuah syarikat penghantaran ingin menyambungkan lima pusat pengedaran dengan kos kabel minimum. Terangkan bagaimana teori graf (pokok rentang minimum) membantu dan apakah kebaikannya berbanding menyambung semua pusat secara terus.", "isi": ["Model: pusat sebagai bucu dan kabel sebagai tepi berwajaran (kos)", "Pokok rentang minimum menyambung semua bucu dengan jumlah wajaran paling kecil tanpa kitaran", "Hanya n − 1 tepi diperlukan bagi n bucu, jadi kos berkurang", "Kaedah Kruskal atau Prim memilih tepi terpendek yang tidak membentuk kitaran"]},{"s": "mt", "t": "Ketaksamaan Linear dalam Dua Pemboleh Ubah", "q": "Sebuah kilang membuat x unit produk A dan y unit produk B. Setiap unit A memerlukan 2 jam dan B memerlukan 3 jam; jumlah masa tidak lebih 60 jam. Terangkan bagaimana ketaksamaan dan rantau berlorek membantu membuat keputusan pengeluaran.", "isi": ["Ketaksamaan: 2x + 3y ≤ 60 dengan x ≥ 0 dan y ≥ 0", "Garis penuh kerana sama dibenarkan; rantau di bawah garis memenuhi had masa", "Setiap titik dalam rantau mewakili gabungan pengeluaran yang mungkin", "Titik pada sempadan menggunakan semua masa yang ada; pengurus boleh memilih yang memberi keuntungan terbaik"]},{"s": "mt", "t": "Graf Gerakan", "q": "Dua kereta menyertai perlumbaan. Graf jarak-masa kereta A lebih curam daripada kereta B. Selepas 2 jam, graf B mendatar. Tafsirkan situasi ini dan bandingkan prestasi kedua-dua kereta.", "isi": ["Kecerunan graf jarak-masa ialah laju; A lebih curam bermakna A lebih laju", "Garis mendatar bagi B bermakna B berhenti (jarak tetap)", "Purata laju = jumlah jarak ÷ jumlah masa, termasuk masa berhenti", "Maka B mempunyai purata laju lebih rendah walaupun sebelum itu bergerak"]},{"s": "mt", "t": "Sukatan Serakan Data Tak Terkumpul", "q": "Dua pemain bola jaring mempunyai min jaringan 10 gol seperti yang sama, tetapi sisihan piawai pemain P ialah 1.2 dan pemain Q ialah 4.5. Pemain manakah yang anda pilih untuk perlawanan penting? Wajarkan.", "isi": ["Min yang sama menunjukkan purata prestasi setara", "Sisihan piawai kecil bermakna jaringan lebih konsisten di sekitar min", "Pemain P lebih boleh dipercayai untuk perlawanan penting", "Pemain Q sesuai jika pasukan memerlukan skor tinggi walaupun berisiko"]},{"s": "mt", "t": "Kebarangkalian Peristiwa Bergabung", "q": "Dalam satu beg ada 4 bola merah dan 6 bola biru. Dua bola dipilih tanpa pulangan. Terangkan mengapa kebarangkalian mendapat dua biru tidak sama dengan kes dengan pulangan dan hitung kedua-duanya.", "isi": ["Tanpa pulangan: peristiwa bersandar kerana jumlah bola berkurang", "Tanpa pulangan: 6/10 × 5/9 = 1/3", "Dengan pulangan: peristiwa bebas, 6/10 × 6/10 = 9/25", "Kebarangkalian berbeza kerana komposisi beg berubah selepas pilihan pertama"]},{"s": "mt", "t": "Matematik Pengguna: Pengurusan Kewangan", "q": "Aina bergaji RM3500 sebulan. Dia mahu menyimpan RM9000 dalam masa 18 bulan untuk membeli komputer riba, tetapi perbelanjaan tetapnya RM2200 dan perbelanjaan lain RM1000 sebulan. Nilaikan sama ada matlamat itu realistik dan cadangkan penyesuaian.", "isi": ["Simpanan diperlukan: 9000 ÷ 18 = RM500 sebulan", "Lebihan wang: 3500 − (2200 + 1000) = RM300 sebulan", "Matlamat belum realistik kerana RM300 < RM500", "Cadangan: kurangkan perbelanjaan lain, cari pendapatan sampingan atau panjangkan tempoh kepada 30 bulan"]},{"s": "mt", "t": "Ubahan", "q": "Masa untuk membersihkan sebuah dewan berubah secara songsang dengan bilangan petugas. Dengan 6 orang, ia siap dalam 4 jam. Jelaskan cara menentukan bilangan petugas jika kerja mesti siap dalam 3 jam, dan apakah andaian model ini?", "isi": ["Ubahan songsang: t = k/n, k = 6 × 4 = 24", "Untuk t = 3: n = 24 ÷ 3 = 8 petugas", "Perlu tambah 2 petugas", "Andaian: semua petugas bekerja dengan kadar sama dan tidak menghalang satu sama lain"]},{"s": "mt", "t": "Matriks", "q": "Sebuah kedai menjual dua jenis kek. Jualan dua cawangan ditulis dalam matriks dan harga dalam satu matriks lajur. Bagaimanakah pendaraban matriks boleh digunakan untuk mengira jumlah jualan setiap cawangan dan apakah kelebihannya?", "isi": ["Matriks jualan (cawangan × jenis kek) didarab dengan matriks harga (jenis kek × 1)", "Hasil ialah matriks jumlah jualan bagi setiap cawangan", "Syarat: bilangan lajur matriks pertama sama dengan bilangan baris matriks kedua", "Kelebihan: mengira banyak data serentak dan mudah diautomasikan dalam hamparan atau program"]},{"s": "mt", "t": "Matematik Pengguna: Insurans", "q": "Encik Rahman membeli polisi komprehensif untuk kereta bernilai RM60000 tetapi enggan membuat tuntutan kecil kerana risau NCD hilang. Terangkan bagaimana deduktibel dan NCD mempengaruhi keputusan tuntutan.", "isi": ["Premium asas dikurangkan oleh NCD apabila tiada tuntutan dibuat", "Deduktibel ialah jumlah yang ditanggung sendiri sebelum syarikat membayar", "Tuntutan kecil yang hampir sama dengan deduktibel kurang berbaloi", "Pertimbangkan kos pembaikan, deduktibel dan kehilangan NCD sebelum membuat tuntutan"]},{"s": "mt", "t": "Matematik Pengguna: Percukaian", "q": "Puan Salmah ialah pekerja bergaji yang menerima gaji RM72000 setahun dan menderma RM1000. Terangkan langkah mengira cukai pendapatan beliau dan mengapa pelepasan serta PCB penting.", "isi": ["Pendapatan bercukai = pendapatan − pengecualian (derma) − pelepasan", "Cukai dikira mengikut banjaran: cukai asas + kadar × baki, kemudian tolak rebat", "PCB ialah potongan bulanan oleh majikan; bandingkan dengan cukai akhir", "Jika PCB melebihi cukai, lebihan dipulangkan; jika kurang, baki perlu dijelaskan"]},{"s": "mt", "t": "Kekongruenan, Pembesaran dan Gabungan Transformasi", "q": "Seorang pereka corak batik menggunakan satu motif asas dan menghasilkan corak berulang. Terangkan transformasi yang boleh digunakan dan bagaimana teselasi memastikan tiada ruang kosong.", "isi": ["Translasi mengalihkan motif tanpa mengubah saiz dan bentuk", "Pantulan dan putaran menghasilkan motif simetri dan arah berbeza", "Pembesaran menukar saiz motif tetapi mengekalkan bentuk", "Teselasi memerlukan jumlah sudut pada setiap bucu ialah 360° supaya tiada jurang atau pertindihan"]},{"s": "mt", "t": "Nisbah dan Graf Fungsi Trigonometri", "q": "Ketinggian air pasang di sebuah pelabuhan berubah mengikut graf yang menyerupai y = 2 sin x + 5. Tafsirkan nilai maksimum, minimum dan kala graf itu dalam situasi sebenar.", "isi": ["Amplitud 2 bermakna air naik dan turun 2 meter daripada aras purata", "Aras maksimum 7 m dan minimum 3 m", "Kala 360° mewakili satu kitaran penuh pasang surut", "Maklumat ini membantu kapal menentukan masa selamat untuk berlabuh"]},{"s": "mt", "t": "Sukatan Serakan Data Terkumpul", "q": "Markah ujian dua kelas dipaparkan dalam ogif. Kelas 5A mempunyai julat antara kuartil 12 dan kelas 5B mempunyai 25 walaupun min sama. Bagaimanakah ogif membantu guru menilai prestasi kelas dan apa tindakan yang sesuai?", "isi": ["Q1, median dan Q3 dibaca daripada ogif pada N/4, N/2 dan 3N/4", "JAK yang lebih kecil bermakna markah lebih tertumpu di tengah", "Kelas 5B lebih berserak: ada murid sangat cemerlang dan ada yang lemah", "Tindakan: bimbingan khusus murid lemah dan pengayaan murid cemerlang di kelas 5B"]},{"s": "mt", "t": "Pemodelan Matematik", "q": "Anda ingin menentukan sama ada berbaloi memandu ke pasar raya lebih jauh untuk membeli dua kampit beras yang lebih murah. Terangkan langkah pemodelan matematik yang akan anda gunakan dan faktor yang perlu dipertimbangkan.", "isi": ["Kenal pasti masalah: bandingkan penjimatan harga dengan kos petrol tambahan", "Andaian dan pemboleh ubah: harga beras, jarak, kadar penggunaan petrol, harga petrol", "Selesaikan: penjimatan = beza harga × bilangan kampit; kos petrol = jarak pergi-balik ÷ km seliter × harga petrol", "Tentusahkan dan laporkan: berbaloi jika penjimatan melebihi kos petrol; murnikan model jika perlu"]},{"s": "bm", "t": "Kata Tunggal, Kata Majmuk dan Kata Terbitan", "q": "Bahasa membezakan kata majmuk, kata terbitan dan kata tunggal. Bagaimanakah pengetahuan ini dapat membantu anda menulis karangan yang tepat bahasanya?", "isi": ["Mengenal pasti ejaan kata majmuk mantap supaya ditulis serangkai", "Menggunakan imbuhan meN- dengan betul termasuk peluluhan bunyi", "Mengelakkan kesalahan seperti 'mempunyai' ditulis 'mempunya'", "Contoh ayat sebenar yang menunjukkan penggunaan yang betul"]},{"s": "bm", "t": "Kata Ganda dan Akronim", "q": "Mengapakah kata ganda dan akronim penting dalam penulisan rasmi? Berikan contoh yang menunjukkan kesilapan biasa dan pembetulannya.", "isi": ["Kata ganda memberi makna jamak, berulang atau pelbagai", "Kesilapan biasa: menggunakan 'banyak' bersama kata ganda", "Akronim memudahkan sebutan nama organisasi", "Mengeja akronim dengan betul menjaga ketepatan tulisan rasmi"]},{"s": "bm", "t": "Kata Nama dan Kata Kerja", "q": "Seorang murid menulis 'Buku itu menulis oleh pengarang terkenal.' Kenal pasti kesalahan dan jelaskan cara membetulkannya dengan merujuk ayat aktif dan pasif.", "isi": ["Ayat pasif menggunakan di- bukan me-", "Pembetulan: Buku itu ditulis oleh pengarang terkenal", "Ayat aktif: Pengarang terkenal menulis buku itu", "Objek ayat aktif menjadi subjek ayat pasif"]},{"s": "bm", "t": "Kata Adjektif dan Kata Tugas", "q": "Bandingkan penggunaan 'dari' dan 'daripada' dalam penulisan formal. Berikan tiga contoh ayat yang tepat dan terangkan peraturannya.", "isi": ["Dari digunakan untuk tempat dan masa", "Daripada digunakan untuk orang, asal bahan, perbandingan", "Contoh: Dia datang dari Johor; hadiah daripada guru", "Kesilapan biasa ialah menggunakan dari bagi perbandingan"]},{"s": "bm", "t": "Frasa", "q": "Sebuah teks mengandungi ayat: 'Pelajar yang rajin itu membaca buku di perpustakaan sekolah.' Huraikan struktur ayat tersebut dengan menggunakan jenis frasa.", "isi": ["Subjek: frasa nama pelajar yang rajin itu", "Predikat: frasa kerja membaca buku", "Frasa sendi nama: di perpustakaan sekolah", "Frasa membantu murid menganalisis ayat panjang"]},{"s": "bm", "t": "Ayat Dasar, Ayat Tunggal dan Ayat Majmuk", "q": "Seorang murid menulis ayat panjang tetapi guru menyatakan ayat itu kurang gramatis. Jelaskan bagaimana mengenal pasti subjek, predikat dan klausa untuk memperbaiki ayat.", "isi": ["Kenal pasti subjek dan predikat dahulu", "Pastikan setiap klausa mempunyai predikat", "Gunakan kata hubung yang sesuai (gabungan atau pancangan)", "Contoh pembetulan ayat tergantung atau tidak lengkap"]},{"s": "bm", "t": "Jenis Ayat", "q": "Gantikan ayat penyata 'Rakan saya tidak hadir hari ini' kepada ayat tanya, perintah dan seruan. Jelaskan perbezaan tanda baca dan intonasi setiap jenis ayat.", "isi": ["Tanya: Mengapakah rakan saya tidak hadir hari ini?", "Perintah: Tolong beritahu rakan saya hadir esok", "Seruan: Wah, rakan saya tidak hadir!", "Perbezaan tanda baca: ?, ., !"]},{"s": "bm", "t": "Peribahasa", "q": "Pilih dua peribahasa yang sesuai untuk menasihati rakan yang suka bergantung kepada orang lain. Terangkan maksud dan cara menggunakannya dalam ayat.", "isi": ["Contoh: Ringan tulang berbanding berat tulang", "Maksud peribahasa dan nilai yang dikaitkan", "Ayat contoh menggunakan peribahasa dengan betul", "Nasihat: berusaha sendiri dan bertanggungjawab"]},{"s": "bm", "t": "Prosa dan Puisi (Seni Bahasa)", "q": "Pilih satu cerpen yang pernah anda baca dan huraikan tema, plot dan nilai murni yang terdapat di dalamnya.", "isi": ["Nyatakan tema dengan jelas", "Huraikan plot: permulaan, perkembangan, klimaks, peleraian", "Nilai murni disokong contoh peristiwa", "Kaitkan pengajaran dengan kehidupan murid"]},{"s": "bm", "t": "Membaca, Memahami dan Menulis dengan Terancang", "q": "Anda diminta menilai sebuah karangan murid yang tidak teratur. Senaraikan langkah menyunting dan penanda wacana yang sesuai untuk menjadikannya lebih tersusun.", "isi": ["Semak ayat topik dan idea utama setiap perenggan", "Tambah penanda wacana: pertama, selain itu, oleh itu", "Betulkan ejaan, tanda baca dan tatabahasa", "Pastikan penutup merumuskan isi karangan"]},{"s": "bm", "t": "Ejaan, Tanda Baca dan Penyuntingan", "q": "Anda diminta menyunting satu karangan rakan yang banyak kesalahan ejaan dan tanda baca. Jelaskan langkah dan contoh pembetulan yang tepat.", "isi": ["Semak huruf besar, di/ke, -nya, -ku", "Betulkan tanda koma dan noktah", "Contoh pembetulan ayat bermasalah", "Baca semula untuk memastikan kesinambungan"]},{"s": "bm", "t": "Kata Hubung dan Penanda Wacana", "q": "Berikan satu perenggan pendek tentang kepentingan membaca dan gunakan sekurang-kurangnya empat kata hubung atau penanda wacana yang betul. Jelaskan fungsi setiap satu.", "isi": ["Gunakan pertama, selain itu, oleh itu, kesimpulannya", "Fungsi: tambahan isi, sebab-akibat, kesimpulan", "Pastikan tiada kata hubung berlebihan seperti agar supaya", "Isi perenggan relevan dan berurutan"]},{"s": "bm", "t": "Ayat Aktif dan Ayat Pasif", "q": "Tukarkan lima ayat aktif kepada ayat pasif dan nyatakan jenis pasif yang digunakan. Mengapakah pasif digunakan dalam laporan rasmi?", "isi": ["Ayat aktif ke pasif diri ketiga (di-)", "Contoh pasif diri pertama dan kedua tanpa imbuhan", "Pasif menumpukan perhatian pada perbuatan atau hasil", "Nada formal dan objektif"]},{"s": "bm", "t": "Ayat Majmuk: Gabungan, Pancangan dan Campuran", "q": "Tulis tiga ayat majmuk (gabungan, pancangan dan campuran) tentang kepentingan menjaga alam sekitar dan tandakan klausa utama serta klausa bawahan.", "isi": ["Contoh gabungan dengan dan atau tetapi", "Contoh pancangan dengan yang, kerana atau supaya", "Contoh campuran yang menggabungkan keduanya", "Tandakan klausa utama dan bawahan"]},{"s": "bm", "t": "Kesalahan Ayat dan Laras Bahasa", "q": "Seorang rakan menulis: 'Para pelajar-pelajar yang hadir di mana dewan adalah untuk supaya mendengar ceramah.' Kenal pasti kesalahan dan betulkan ayat tersebut.", "isi": ["Para pelajar (bukan para pelajar-pelajar)", "Di mana tidak sesuai; gunakan di dewan atau tempat", "Elakkan untuk supaya, adalah yang berlebihan", "Contoh pembetulan: Para pelajar yang hadir di dewan mendengar ceramah"]},{"s": "bm", "t": "Peribahasa dan Gaya Bahasa", "q": "Pilih satu keadaan, misalnya hari pertama sekolah, dan tulis dua ayat menggunakan personifikasi dan simile. Jelaskan kesan gaya bahasa tersebut kepada pembaca.", "isi": ["Contoh simile dan personifikasi yang tepat", "Gambaran imej yang jelas", "Kesan: menghidupkan penerangan dan menarik pembaca", "Elakkan penggunaan gaya bahasa yang berlebihan"]},{"s": "bm", "t": "Unsur Karya Sastera: Sajak, Cerpen, Novel dan Drama", "q": "Pilih satu karya sastera dan huraikan hubungan antara watak, plot dan latar dalam menyampaikan tema. Berikan satu nilai murni yang boleh dicontohi.", "isi": ["Nyatakan tajuk dan tema karya", "Huraikan watak dan perwatakan", "Huraikan plot dan latar yang menyokong tema", "Nilai murni dengan bukti peristiwa"]},{"s": "bm", "t": "Penulisan: Karangan, Rumusan dan Penulisan Rasmi", "q": "Anda perlu menulis rumusan teks tentang kesan penggunaan telefon pintar kepada remaja. Terangkan langkah-langkah menulis rumusan yang ringkas dan tepat.", "isi": ["Baca dan tanda isi penting", "Buang contoh dan huraian panjang", "Tulis semula dengan ayat sendiri", "Semak bilangan patah perkataan dan kesinambungan"]},{"s": "bi", "t": "Listening: Main Ideas, Details and Attitudes", "q": "You listen to a talk about the effects of social media on teenagers. Explain how you would identify the main idea, two details and the speaker's attitude.", "isi": ["Main idea: overall point about social media effects", "Details: specific facts, examples or statistics", "Attitude: shown through tone and words like worried, positive", "Use signal words and keywords to organise notes"]},{"s": "bi", "t": "Guessing Meaning from Context", "q": "A text contains the sentence: 'The villagers were destitute; they had lost their homes and had no food.' Explain how you would guess the meaning of 'destitute'.", "isi": ["Look at the surrounding clues: lost homes and no food", "Identify the type of clue (example/explanation)", "Infer: very poor, lacking basic needs", "Check with a dictionary to confirm"]},{"s": "bi", "t": "Speaking: Explaining, Justifying and Using Register", "q": "You are asked to give a two-minute talk on whether students should be allowed to use phones in school. Describe how you would explain advantages and disadvantages, justify your view and use suitable register.", "isi": ["State opinion clearly", "Advantages with reasons and examples", "Disadvantages and balanced view", "Use formal register and polite phrases"]},{"s": "bi", "t": "Reading: Main Points, Details and Writer's Attitude", "q": "Choose a short article you have read. Describe how you would identify the main points, supporting details and the writer's attitude.", "isi": ["Topic sentences show main points", "Supporting details: examples, facts, reasons", "Writer's attitude through adjectives, adverbs, tone", "Separate fact from opinion"]},{"s": "bi", "t": "Reading: Text Types and Features", "q": "Compare a news report with a blog post on the same issue. Explain the differences in purpose, language and structure.", "isi": ["News report: objective, facts, headline, lead paragraph", "Blog: personal voice and opinion", "Language features: formal vs informal", "Reliability and audience"]},{"s": "bi", "t": "Writing: Explaining Visuals, Causes and Consequences", "q": "Describe how you would explain a graph showing increasing electricity use in a town, including the causes and consequences of the increase.", "isi": ["Introduce what the graph shows", "Describe trends using increase, rise and figures", "Explain causes (population growth, more appliances)", "Explain consequences (higher bills, more pollution)"]},{"s": "bi", "t": "Writing: Organising Ideas and Opinion Texts", "q": "Write a plan for an essay arguing whether school uniforms should be compulsory. Show your stand, three supporting points with examples, and a conclusion.", "isi": ["Introduction with clear stand", "Point 1 with reason and example", "Point 2 with reason and example", "Conclusion restating stand and summarising"]},{"s": "bi", "t": "Writing Accuracy: Punctuation, Spelling and Register", "q": "Rewrite the informal message 'Hey boss, can't come tmrw coz sick, sorry' as a formal email to a supervisor and explain the changes in punctuation and register.", "isi": ["Use formal greeting and closing", "Write full words: cannot, tomorrow, because", "Add punctuation and capital letters", "Polite expressions: I apologise for the inconvenience"]},{"s": "bi", "t": "Grammar: Tenses, Subject-Verb Agreement and Articles", "q": "A student writes: 'Yesterday, I go to the library and borrow an books. The librarians is very helpful.' Identify and correct the errors, explaining the grammar rules.", "isi": ["Past tense: went, borrowed", "Articles: some books or a book", "Subject-verb agreement: The librarian is / The librarians are", "Explain rule for each correction"]},{"s": "bi", "t": "Literature in Action: Plot, Character, Theme and Style", "q": "Choose a short story or poem from your syllabus. Explain how plot, characters and style help communicate the theme, and give a personal response.", "isi": ["State the theme clearly", "Show how plot develops the theme", "Characters and their actions as evidence", "Stylistic features and personal response"]},{"s": "bi", "t": "Listening: Longer Texts and Complex Questions", "q": "You listen to a ten-minute interview about renewable energy. Explain how you would note the main ideas, answer complex questions and avoid being misled by distractors.", "isi": ["Use keywords and signal words", "Note cause and effect with arrows", "Check the whole option against what was said", "Review answers after listening"]},{"s": "bi", "t": "Speaking: Discussing, Summarising and Presenting", "q": "You are asked to present a three-minute talk on the benefits of volunteering. Outline the structure of your talk and the language you would use to introduce, develop and conclude it.", "isi": ["Introduction with hook and topic", "Three points with reasons and examples", "Signposting: firstly, next, finally", "Conclusion and polite closing"]},{"s": "bi", "t": "Reading: Inference, Fact and Opinion, Bias", "q": "Read two articles on the same issue that present different views. Explain how you would identify bias, separate facts from opinions and evaluate the reliability of each article.", "isi": ["Identify emotive words and one-sided arguments", "List facts and opinions separately", "Check evidence and sources", "Compare and judge reliability"]},{"s": "bi", "t": "Reading: Informational Texts (News, Emails, Notices, Advertisements)", "q": "Choose an advertisement or notice you have read. Explain the persuasive devices, key information and how you would check whether its claims are reliable.", "isi": ["Identify key information: what, when, where", "Persuasive devices: slogan, rhetorical questions", "Check evidence and source", "Judge if claims are reliable"]},{"s": "bi", "t": "Writing: Formal and Informal Emails and Letters", "q": "Write an outline for a formal email to your school principal requesting permission to organise a charity run, and an informal email to a friend inviting them to join.", "isi": ["Formal: greeting, purpose, details, request, closing", "Informal: friendly greeting, invitation, details, casual closing", "Register differences", "Proofread both"]},{"s": "bi", "t": "Writing: Articles, Reviews and Reports", "q": "Choose a recent book or film. Outline a review that evaluates its strengths and weaknesses and makes a recommendation. Then outline a short report on a school activity.", "isi": ["Review: summary, strengths, weaknesses, recommendation", "Report: title, introduction, findings, conclusion, recommendations", "Language: evaluative vs formal objective", "Use connectors and evidence"]},{"s": "bi", "t": "Grammar: Conditionals, Passive Voice, Reported Speech and Connectors", "q": "Rewrite the following in the form indicated: (a) a first conditional about studying and passing, (b) a passive sentence about a school event, (c) reported speech of a teacher's advice. Explain the grammar rules.", "isi": ["First conditional structure and example", "Passive voice with be + past participle", "Reported speech: tense backshift", "Choose suitable connectors"]},{"s": "bi", "t": "Literature: Poems, Short Stories and Novel Components", "q": "Choose a poem, short story or novel from your syllabus. Explain how the characters and events show a theme, and write a short imaginative response such as a diary entry.", "isi": ["State theme and support with events", "Analyse character through actions and words", "Use quotes or references", "Write an imaginative response consistent with the text"]}];
