  try { c = JSON.parse(localStorage.getItem("gt-kb-cfg") || "null"); if (c) ingat = 1; } catch (e) { c = null; }
  if (!c) { try { c = JSON.parse(sessionStorage.getItem("gt-kb-cfg") || "null"); } catch (e) { c = null; } }
