    c.append(el("b", null, "Tahap " + (i + 1) + ": " + a.n), el("span", { class: "muted", style: "font-size:14px" }, "Perisai permulaan " + a.st + ". Menyerap " + Math.round(a.ab * 100) + "% kerosakan sehingga perisai habis."), b);
