    const nose = new T3.Mesh(new T3.CylinderGeometry(0.01, 0.11, 0.3, 8), lam(0xb03a2a)); nose.rotation.x = -Math.PI / 2; nose.position.z = -0.55;
    g.add(body, nose); g.rotation.order = "YXZ"; g.rotation.set(Math.asin(vy / 48), Math.atan2(-vx, -vz), 0);
    g.position.set(sx, sy, sz); missionG.add(g); r.m = g;
