  b.hp -= d; flashSoldier(b);
  beep(d > 25 ? 1200 : 800, 0.06, "square", 0.05);
  if (b.hp > 0) return;
  b.dead = true; b.deadT = 0; if (b.isSniper) sniperDown(b);
