  S.hp -= d;
  if (!fromZone) {
    $("hit").classList.add("on");
    setTimeout(() => $("hit").classList.remove("on"), 160);
    beep(120, 0.15, "square", 0.07);
    try { onHurt(d); } catch (e) { /* abaikan */ }
  }
