  const rnd = Math.random;
  const sp = randomSpot(rnd, 10, HALF - 20, null, 0);
  pl.x = sp.x; pl.z = sp.z; pl.y = 0; pl.vy = 0; pl.landed = true;
  S.hp = 100; S.deadT = 0;
