  const hull = new T3.Mesh(new T3.BoxGeometry(2.8, 1.3, 6.0), hullM); hull.position.y = 1.15;
  const front = new T3.Mesh(new T3.BoxGeometry(2.6, 0.9, 1.6), hullM); front.position.set(0, 0.95, -3.6);
  const turret = new T3.Group(); turret.position.set(0, 2.1, 0.3);
  const tb = new T3.Mesh(new T3.BoxGeometry(1.6, 0.7, 1.8), hullM); tb.position.y = 0.2;
  const barrel = new T3.Mesh(new T3.BoxGeometry(0.16, 0.16, 2.2), darkM); barrel.position.set(0, 0.25, -1.6);
  turret.add(tb, barrel);
  g.add(hull, front, turret);
