  const pos = { x: a.x, z: a.z }, bx = pos.x, bz = pos.z;
  pushOut(pos, 2.3, 0);
  if (Math.hypot(pos.x - bx, pos.z - bz) > 0.02) a.wt = Math.min(a.wt, 0.4);
  a.x = clamp(pos.x, -HALF + 4, HALF - 4); a.z = clamp(pos.z, -HALF + 4, HALF - 4);
  a.g.position.set(a.x, 0, a.z); a.g.rotation.y = a.yaw;
  let ta = Math.atan2(-dx, -dz) - a.yaw; while (ta > Math.PI) ta -= 2 * Math.PI; while (ta < -Math.PI) ta += 2 * Math.PI;
