    const p = M.mp ? randomSpot(rng(((M.seed | 0) ^ 0xb055) >>> 0), 12, HALF - 14) : randomSpot(Math.random, 12, HALF - 14, pl, 45);
    const s = makeSoldier(0xe0b341, 0xe0b341, 0x5a1d1d, { acc: "", lvl: 3, ex: "jen" });
    s.isBot = true; s.isBoss = true; s.max = 900; s.hp = 900; s.x = p.x; s.z = p.z; s.tgt = null; s.wt = 0; s.dead = false; s.deadT = 0;
    s.strafe = 1; s.strafeT = 1.5; s.shootT = 2; s.burst = 0; s.burstT = 0; s.shield = true; s.ph2 = false; s.openT = 0; s.cool = 0; s.shNote = -99; s.fn = 0; s.fnSeen = 0; s.sx = p.x; s.sz = p.z; s.sw = 0; s.snapInit = false; s.tg = ""; s.kb = "";
