  if (!b || b.dead || !S.running) { bb.hidden = true; return; }
  bb.hidden = false; bb.classList.toggle("sh", !!b.shield);
  $("bossHp").style.width = clamp(b.hp / b.max, 0, 1) * 100 + "%";
