const AR_TEST = /[؀-ۿݐ-ݿ]/;
const AR_RUN = /[؀-ۿݐ-ݿ](?:[؀-ۿݐ-ݿ\s_ـ]*[؀-ۿݐ-ݿ_])?/g;
function arStart(l) { const m = l.match(/[A-Za-z؀-ۿݐ-ݿ]/); return !!m && AR_TEST.test(m[0]); }
function qSet(e, t) {
  t = String(t); e.textContent = "";
  if (!AR_TEST.test(t) && t.indexOf("\n") < 0) { e.textContent = t; return e; }
  t.split("\n").forEach((l) => { const d = el("div"); if (arStart(l)) { d.className = "ar-line"; d.dir = "rtl"; } d.textContent = l; e.appendChild(d); });
  return e;
}
function arFixNode(n) {
  const p = n.parentNode;
  if (!p || /^(SCRIPT|STYLE|TEXTAREA|OPTION)$/.test(p.nodeName) || (p.closest && p.closest(".ar-line,.ar-in,svg"))) return;
  const s = n.nodeValue; if (!AR_TEST.test(s)) return;
  const f = document.createDocumentFragment(); let last = 0, m; AR_RUN.lastIndex = 0;
  while ((m = AR_RUN.exec(s))) {
    if (m.index > last) f.appendChild(document.createTextNode(s.slice(last, m.index)));
    const b = document.createElement("bdi"); b.className = "ar-in"; b.dir = "rtl"; b.textContent = m[0]; f.appendChild(b);
    last = m.index + m[0].length;
  }
  if (last < s.length) f.appendChild(document.createTextNode(s.slice(last)));
  p.replaceChild(f, n);
}
function arFix(root) {
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, null), list = [];
  let n; while ((n = w.nextNode())) if (AR_TEST.test(n.nodeValue)) list.push(n);
  list.forEach(arFixNode);
}
