/* ---------- Gelung ---------- */
let lastT = performance.now(), hudT = 0, miniT = 0, loopOn = false;
function loop(now) {
  /* v17.87: gelung berhenti apabila lapisan permainan disembunyikan; dihidupkan semula oleh pemerhati di bawah */
  if ($("game").hidden) { loopOn = false; return; }
  requestAnimationFrame(loop);
  const dt = Math.min(0.05, (now - lastT) / 1000);
  gfxTick(now - lastT);
  const lastT0 = lastT;
  lastT = now;
  if (!renderer || !M || $("game").hidden) { if (DIAG.on) diagFrame(now - lastT0, 0, 0, 0); return; }
  const p0 = performance.now();
  if (S.running && !S.over) {
    try { ambTick(); musTick(dt); } catch (e) { DIAG.err++; DIAG.last = String(e.message).slice(0, 90); }
    try {
      if (!S.inQuiz && !S.paused) update(dt);
      else if (M.mp) { sendPresence(dt); recvPeers(dt); }
    } catch (e) { DIAG.err++; DIAG.last = String(e.message).slice(0, 90); }
  }
  const p1 = performance.now();
  if (S.running && !S.over) {
    try {
      hudT -= dt; if (hudT <= 0) { hudT = 0.12; updateHud(); }
      miniT -= dt; if (miniT <= 0) { miniT = 0.066; drawMini(); }
    } catch (e) { DIAG.err++; DIAG.last = String(e.message).slice(0, 90); }
  }
  const p2 = performance.now();
  try { scopeUpdate(dt); } catch (e) { DIAG.err++; DIAG.last = String(e.message).slice(0, 90); }
  gun.visible = S.running && !S.over && !S.scoped && !(S.tank && S.tank.bike);
  renderer.render(scene, camera);
  diagFrame((now - lastT0) , p1 - p0, performance.now() - p2, p2 - p1);
}
function loopStart() { if (loopOn || $("game").hidden) return; loopOn = true; lastT = performance.now(); requestAnimationFrame(loop); }
new MutationObserver(loopStart).observe($("game"), { attributes: true, attributeFilter: ["hidden"] });
loopStart();

