    e[2] = Date.now();
    c.t++; c.sj[SUBJ] = (c.sj[SUBJ] | 0) + 1;
    if (ok) { c.o++; c.r++; if (c.r > c.b) c.b = c.r; } else c.r = 0;
    if (ok) {
      e[1]++;
      if (e[3] >= 0 && e[4] <= td) { e[3]++; if (e[3] >= LRN_GAP.length) { e[3] = -2; c.ms++; } else e[4] = td + LRN_GAP[e[3]]; }
    } else { e[0]++; e[3] = 0; e[4] = td + LRN_GAP[0]; }
