  const box = [[d.n, "Murid"], [d.act + " (" + (d.n ? Math.round(d.act * 100 / d.n) : 0) + "%)", "Aktif 7 hari"], [d.ans, "Soalan dijawab dalam misi"], [d.ans ? Math.round(d.ok * 100 / d.ans) + "%" : "-", "Ketepatan keseluruhan"]];
  box.forEach((b, i) => { const x = 70 + i * 280; g.fillStyle = "#fff"; g.fillRect(x, 250, 260, 170); g.strokeStyle = "#d8cfae"; g.lineWidth = 3; g.strokeRect(x, 250, 260, 170); certText(g, String(b[0]), x + 130, 345, "700 54px " + SANS, ACC, "center", 0, 230); certText(g, b[1], x + 130, 395, "600 22px " + SANS, MUT, "center", 0, 236); });
  let y = 500;
