  d.top.forEach((x, i) => { certText(g, (i + 1) + ".", 70, y, "700 28px " + SANS, ACC, "left", 0); certText(g, x.nama + (x.kelas ? " (" + x.kelas + ")" : ""), 120, y, "600 28px " + SANS, INK, "left", 0, 520); certText(g, x.pangkat + " | " + x.xp + " XP | " + x.m + " misi | streak " + x.fl + " hari", W - 70, y, "500 24px " + SANS, MUT, "right", 0, 540); y += 50; });
  y += 40; certText(g, "TOPIK PERLU PERHATIAN", 70, y, "700 30px " + SANS, INK, "left", 4); y += 20; g.fillStyle = ACC; g.fillRect(70, y, 120, 6); y += 50;
  d.weak.forEach((x) => { const pc = x.acc != null ? Math.round(x.acc * 100) : Math.round(x.pct * 100); certText(g, guruLab(x.t) + "  " + x.t.nama, 70, y, "600 26px " + SANS, INK, "left", 0, 760); g.fillStyle = "#e6dfc3"; g.fillRect(860, y - 24, 220, 20); g.fillStyle = pc < 50 ? "#c0453a" : ACC; g.fillRect(860, y - 24, 220 * pc / 100, 20); certText(g, pc + "%" + (x.acc != null ? "" : " selesai"), W - 70, y, "700 24px " + SANS, INK, "right", 0); y += 50; });
  y += 40; certText(g, "KEMAJUAN MENGIKUT TOPIK", 70, y, "700 30px " + SANS, INK, "left", 4); y += 20; g.fillStyle = ACC; g.fillRect(70, y, 120, 6); y += 44;
  const rowH = Math.max(28, Math.min(40, Math.floor((H - 150 - y) / Math.max(1, d.tp.length))));
  d.tp.forEach((x, i) => { if (y > H - 130) return; if (i % 2 === 0) { g.fillStyle = "#f2ecd6"; g.fillRect(60, y - rowH + 10, W - 120, rowH); } certText(g, guruLab(x.t) + "  " + x.t.nama, 74, y, "500 " + Math.round(rowH * 0.62) + "px " + SANS, INK, "left", 0, 760); certText(g, x.done + "/" + d.n + " murid", 980, y, "500 " + Math.round(rowH * 0.58) + "px " + SANS, MUT, "right", 0); certText(g, x.acc != null ? Math.round(x.acc * 100) + "%" : "-", W - 74, y, "700 " + Math.round(rowH * 0.62) + "px " + SANS, INK, "right", 0); y += rowH; });
  certText(g, "Dijana oleh Gempur. Ketepatan dikira daripada jawapan misi Tempur. Bukan dokumen rasmi KPM.", W / 2, H - 50, "500 18px " + SANS, MUT, "center", 0, W - 120);
  const blob = await new Promise((r) => c.toBlob(r, "image/jpeg", 0.92));
