    let v;
    try { v = (await FB.req("GET", "komen", undefined, "orderBy=%22t%22&limitToLast=100")) || {}; }
    catch (e) { if (e.code === 400) v = (await FB.req("GET", "komen")) || {}; else throw e; }
    KM.list = Object.keys(v).map((id) => Object.assign({ id: id }, v[id])).filter((x) => x && typeof x.m === "string" && x.t).sort((a, b) => b.t - a.t).slice(0, 100);
