  KM.armed = "";
  try { await kmAdmReq("DELETE", "komen/" + id); await kmAdmReq("DELETE", "komen_lapor/" + id).catch(() => {}); KM.list = KM.list.filter((x) => x.id !== id); KM.msg = "Komen dipadam."; }
  catch (e) { KM.msg = e.code === 401 || e.code === 403 ? "Kunci moderator tidak sah. Log keluar moderator dan cuba lagi." : "Gagal memadam komen."; }
