    const role = String(x.r || "").slice(0, 12);
    top.append(el("b", null, String(x.n || "Pengguna").slice(0, 30)), el("span", { class: "km-role km-" + (role === "Guru" ? "g" : role === "Ibu bapa" ? "i" : "m") }, role || "Murid"), el("span", { class: "muted" }, kmAgo(x.t)));
