/* ---------- Kelas, tugasan, ujian bermasa, soalan guru, analisis (v17.59) ---------- */
const KK = { cfg: {}, data: null, code: "", mem: {}, mine: {}, resAll: {}, open: "", an: "", err: "", msg: "", loading: false, join: "", sel: "" };
