function kkId(p) { return p + Date.now().toString(36) + Math.random().toString(36).slice(2, 5); }
function kkTasks() { const t = (KK.data && KK.data.tg) || {}; return Object.keys(t).map((id) => Object.assign({ id: id }, t[id])).sort((a, b) => (b.t | 0) - (a.t | 0)); }
