/* ----- muat data kelas ----- */
async function kkLoad(code, keepMsg) {
  KK.loading = true; KK.err = ""; if (!keepMsg) KK.msg = ""; renderKelas();
  try {
    const d = await FB.req("GET", "kelas/" + code);
    if (!d || !d.i) { KK.err = "Kod kelas tidak ditemui."; KK.data = null; KK.loading = false; renderKelas(); return false; }
    KK.data = d; KK.code = code;
    KK.mem = (await FB.req("GET", "kelas_ahli/" + code)) || {};
    KK.mine = {};
    if (gtRole() !== "guru") await Promise.all(kkTasks().map(async (t) => { try { const r = await FB.req("GET", "kelas_skor/" + code + "/" + t.id + "/" + FB.getUid()); if (r) KK.mine[t.id] = r; } catch (e) { /* abaikan */ } }));
  } catch (e) { KK.err = "Gagal memuatkan kelas. Semak sambungan internet dan peraturan Firebase."; }
  KK.loading = false; renderKelas(); return !KK.err;
}
async function kkAhli(code) { try { await FB.req("PUT", "kelas_ahli/" + code + "/" + FB.getUid(), { n: cleanName(P.nama) || "Murid", k: String(P.kelas || "").slice(0, 12), t: Date.now() }); } catch (e) { /* abaikan */ } }
async function kkJoin(raw) {
  const code = String(raw || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
  if (code.length !== 6) { KK.err = "Kod kelas mesti 6 aksara."; renderKelas(); return; }
  if (!P.nama) { KK.err = "Daftar nama anda dahulu (tekan nama di penjuru atas)."; renderKelas(); return; }
  KK.err = "";
  if (!(await kkLoad(code))) return;
  kkSet("gt-kelas-saya", { c: code, n: KK.data.i.n, sj: KK.data.i.sj }); await kkAhli(code);
  KK.msg = "Anda telah menyertai kelas " + KK.data.i.n + "."; try { localStorage.removeItem("gt-join"); } catch (e) { /* abaikan */ } await kkLoad(code, true);
}
function kkLeave() { try { localStorage.removeItem("gt-kelas-saya"); } catch (e) { /* abaikan */ } KK.data = null; KK.code = ""; KK.msg = "Anda telah keluar daripada kelas."; renderKelas(); }

/* ----- guru: cipta kelas, tugasan, soalan sendiri ----- */
async function kkCreate(nama) {
  nama = String(nama || "").replace(/[\u0000-\u001f<>]/g, "").trim().slice(0, 40);
  if (nama.length < 3) { KK.err = "Nama kelas terlalu pendek."; renderKelas(); return; }
  if (!P.sekolah) { KK.err = "Daftar sekolah anda dahulu."; renderKelas(); return; }
  for (let k = 0; k < 5; k++) {
    const code = kkNewCode();
    try {
      await FB.req("PUT", "kelas/" + code + "/i", { n: nama, sk: cleanSekolah(P.sekolah).slice(0, 60), sid: mySid() || "", ng: P.negeri || "", sj: SUBJ, g: FB.getUid(), t: Date.now() });
      const l = kkTeachList(); l.push({ c: code, n: nama, sj: SUBJ }); kkSet("gt-kelas-guru", l); KK.sel = code; KK.err = ""; KK.msg = "Kelas dicipta. Kongsi kod atau kod QR dengan murid."; await kkLoad(code, true); return;
    } catch (e) { if (e.code !== 401 && e.code !== 403) break; }
  }
  KK.err = "Gagal mencipta kelas. Pastikan peraturan Firebase untuk 'kelas' sudah dipasang."; renderKelas();
}
async function kkAddTask(f) {
  const nama = f.nama.replace(/[\u0000-\u001f<>]/g, "").trim().slice(0, 50), ujian = f.jenis === "u";
  const sl = (KK.data && KK.data.sl) || {}, custom = f.guna ? Object.keys(sl) : [];
  let pool = []; f.topik.forEach((t) => { pool = pool.concat((BYTOPIK[t] || []).map((q) => q.i)); });
  pool = shuffle(pool.filter((v, i, a) => a.indexOf(v) === i));
  const bil = clamp(f.bil | 0, 3, 50), ids = custom.slice(0, bil).concat(pool.slice(0, Math.max(0, bil - custom.length)));
  if (nama.length < 3) { KK.err = "Tajuk tugasan terlalu pendek."; renderKelas(); return; }
  if (ids.length < 3) { KK.err = "Pilih sekurang-kurangnya satu topik (atau tambah soalan sendiri) supaya ada 3 soalan atau lebih."; renderKelas(); return; }
  const mn = ujian ? clamp(f.mn | 0, 5, 120) : 0;
  try {
    await FB.req("PUT", "kelas/" + KK.code + "/tg/" + kkId("t"), { n: nama, sj: SUBJ, q: ids, x: ujian ? "u" : "t", mn: mn, d: f.tarikh || "", t: Date.now() });
    KK.err = ""; KK.msg = "Tugasan dihantar kepada kelas (" + ids.length + " soalan)."; await kkLoad(KK.code, true);
  } catch (e) { KK.err = "Gagal mencipta tugasan."; renderKelas(); }
}
async function kkAddQ(f) {
  const q = f.q.replace(/\s+/g, " ").trim(), o = f.o.map((x) => x.replace(/\s+/g, " ").trim());
  if (q.length < 6 || o.some((x) => !x) || new Set(o.map((x) => x.toLowerCase())).size < 4) { KK.err = "Isi soalan dan 4 pilihan jawapan yang berbeza."; renderKelas(); return; }
  if (kmBad(q) || o.some(kmBad)) { KK.err = "Soalan mengandungi kata tidak sesuai, pautan atau nombor telefon."; renderKelas(); return; }
  try {
    await FB.req("PUT", "kelas/" + KK.code + "/sl/" + kkId("C"), { q: q.slice(0, 300), o: o.map((x) => x.slice(0, 120)), a: f.a | 0, e: String(f.e || "").trim().slice(0, 300), t: Date.now() });
    KK.err = ""; KK.msg = "Soalan ditambah."; await kkLoad(KK.code, true);
  } catch (e) { KK.err = "Gagal menambah soalan."; renderKelas(); }
}
async function kkResults(tid) {
  KK.open = tid; KK.an = "";
  try { KK.resAll[tid] = (await FB.req("GET", "kelas_skor/" + KK.code + "/" + tid)) || {}; } catch (e) { KK.err = "Gagal memuatkan keputusan."; }
  renderKelas();
}
function kkResRows(tid) {
  const r = KK.resAll[tid] || {}, rows = [], seen = {};
  Object.keys(r).forEach((u) => { seen[u] = 1; rows.push({ u: u, n: r[u].n || (KK.mem[u] && KK.mem[u].n) || "Murid", k: r[u].k || (KK.mem[u] && KK.mem[u].k) || "", ok: r[u].ok | 0, tot: r[u].tot | 0, s: r[u].s | 0, a: String(r[u].a || ""), t: r[u].t | 0, done: true }); });
  Object.keys(KK.mem).forEach((u) => { if (!seen[u]) rows.push({ u: u, n: KK.mem[u].n || "Murid", k: KK.mem[u].k || "", ok: 0, tot: 0, s: 0, a: "", t: 0, done: false }); });
  return rows.sort((a, b) => (b.done - a.done) || b.ok - a.ok || a.n.localeCompare(b.n));
}
function kkAnalysis(tg) {
  const rows = kkResRows(tg.id).filter((x) => x.done), qs = (tg.q || []).map((id) => kkQ(id));
  return qs.map((q, i) => {
    const c = [0, 0, 0, 0], n = rows.length; let ans = 0;
    rows.forEach((r) => { const ch = r.a.charAt(i); if (ch >= "0" && ch <= "3") { c[+ch]++; ans++; } });
    return { q: q, i: i, c: c, n: n, ans: ans, ok: q ? c[q.a] : 0, pct: q && ans ? c[q.a] / ans : null };
  });
}
function kkFmtS(s) { return Math.floor(s / 60) + ":" + String(s % 60).padStart(2, "0"); }
function kkCsv(tg) {
  const L = [["Nama", "Kelas", "Markah", "Jumlah soalan", "Peratus", "Masa", "Tarikh hantar"].map(guruCsvCell).join(",")];
  kkResRows(tg.id).forEach((r) => L.push([r.n, r.k, r.done ? r.ok : "", r.done ? r.tot : "", r.done && r.tot ? Math.round(r.ok * 100 / r.tot) + "%" : "Belum hantar", r.done ? kkFmtS(r.s) : "", r.t ? new Date(r.t).toISOString().slice(0, 10) : ""].map(guruCsvCell).join(",")));
  const a = el("a", { href: URL.createObjectURL(new Blob(["﻿" + L.join("\n")], { type: "text/csv;charset=utf-8" })), download: "keputusan-" + (tg.n || "tugasan").replace(/[^A-Za-z0-9]+/g, "-") + ".csv" });
  document.body.appendChild(a); a.click(); a.remove();
}

/* ----- PDF berbilang halaman daripada kanvas ----- */
