    offs[p] = off; str(p + " 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /XObject << /Im0 " + m + " 0 R >> >> /Contents " + c + " 0 R >>\nendobj\n");
