    let y = 230, x0 = 60; const tw = W - 120, sum = widths.reduce((a, b) => a + b, 0);
    g.fillStyle = "#e6dfc3"; g.fillRect(x0, y - 32, tw, 44);
    let x = x0; head.forEach((h, i) => { const w = tw * widths[i] / sum; certText(g, h, x + 10, y, "700 22px " + SANS, "#1f2a1a", "left", 0, w - 16); x += w; }); y += 48;
    rows.slice(p * per, (p + 1) * per).forEach((r, ri) => { if (ri % 2) { g.fillStyle = "#f2ecd6"; g.fillRect(x0, y - 30, tw, 44); } let xx = x0; r.forEach((v, i) => { const w = tw * widths[i] / sum; certText(g, String(v), xx + 10, y, "500 22px " + SANS, "#1f2a1a", "left", 0, w - 16); xx += w; }); y += 46; });
    certText(g, "Halaman " + (p + 1) + " / " + np + " | Dijana oleh Gempur", W / 2, H - 40, "500 18px " + SANS, "#55633f", "center", 0, W - 120);
