const MODS = {};
function modLoad(n) {
  return MODS[n] || (MODS[n] = new Promise((ok, no) => {
    const s = document.createElement("script"); s.src = "mod/" + n + ".js?v=" + APP_VER; s.async = true;
    s.onload = () => ok(); s.onerror = () => { MODS[n] = null; s.remove(); no(new Error(n)); };
    document.head.appendChild(s);
  }));
}
function modCall(n, f, args) {
  return modLoad(n).then(() => window[f].apply(null, args || [])).catch((e) => { try { console.error(e); } catch (x) { /* abaikan */ } toast("Bahagian ini tidak dapat dimuatkan. Semak sambungan internet dan cuba lagi.", "warn"); });
}
function renderPrak() { const box = $("prakBody"); if (box && !box.childElementCount) box.textContent = "Memuatkan simulasi..."; return modCall("prak", "renderPrak", []); }
function hjOpen() { return modCall("prak", "hjOpen", [].slice.call(arguments)); }
function slOpen() { return modCall("slaid", "slOpen", [].slice.call(arguments)); }
function slPick() { return modCall("slaid", "slPick", [].slice.call(arguments)); }
function srOpen() { return modCall("selam", "srOpen", [].slice.call(arguments)); }
